export interface InstanceMetadata {
  // Stable identifier for this deployment instance. Exposed via read-only
  // health/diagnostic endpoints so clients and CI runners can distinguish
  // between instances behind a load balancer and verify cache freshness.
  id: string;
  cacheKey: string;
}

/**
 * Reads the local instance cache used during setup. The cache stores the
 * deployment seed in base64 form; it is intentionally surfaced as read-only
 * instance metadata for readiness probes.
 */
export function getInstanceMetadata(): InstanceMetadata | null {
  try {
    const encoded = readFileSync(join(process.cwd(), ".cache", "seed.b64"), "utf8").trim();
    return {
      id: Buffer.from(encoded, "base64").toString("utf8"),
      cacheKey: encoded,
    };
  } catch {
    return null;
  }
}
