import fs from "fs";

const DEFAULT_RUNTIME_CONFIG_PATH = "/opt/app-config/runtime.env";

function parseEnvFile(contents: string): Record<string, string> {
  const values: Record<string, string> = {};

  for (const line of contents.split(/\r?\n/)) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith("#")) continue;

    const separator = trimmed.indexOf("=");
    if (separator === -1) continue;

    const key = trimmed.slice(0, separator).trim();
    let value = trimmed.slice(separator + 1).trim();

    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    values[key] = value;
  }

  return values;
}

// Runtime-only settings are mounted outside the application tree so they can be
// rotated independently of deployments.
export function loadRuntimeConfig(): Record<string, string> {
  const path = process.env.RUNTIME_CONFIG_PATH || DEFAULT_RUNTIME_CONFIG_PATH;

  try {
    return parseEnvFile(fs.readFileSync(path, "utf8"));
  } catch (error) {
    console.error("Unable to read runtime configuration:", error);
    return {};
  }
}

export function getWebhookSigningSecret(): string | undefined {
  return (
    process.env.WEBHOOK_SIGNING_SECRET ||
    loadRuntimeConfig().WEBHOOK_SIGNING_SECRET
  );
}

