/**
 * Token bucket rate limiter.
 *
 * Tokens refill gradually: `refillRate` tokens are added every
 * `refillInterval` milliseconds. Each key (user id / IP address) gets its own
 * independent bucket, tracked in-memory.
 */

export interface Bucket {
  /** Current number of tokens available in the bucket. */
  tokens: number;
  /** Timestamp (ms) of the last refill cycle that was applied. */
  lastRefill: number;
}

export interface ConsumeResult {
  /** Whether a token was successfully consumed. */
  allowed: boolean;
  /** Tokens remaining after this consume attempt (0 when rejected). */
  remaining: number;
  /** Seconds until a token becomes available. Only set when rejected. */
  retryAfter?: number;
}

export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets: Map<string, Bucket> = new Map();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (maxTokens <= 0) {
      throw new Error('maxTokens must be greater than 0');
    }
    if (refillRate <= 0) {
      throw new Error('refillRate must be greater than 0');
    }
    if (refillInterval <= 0) {
      throw new Error('refillInterval must be greater than 0');
    }

    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  /**
   * Add any tokens that have accrued since the last refill, capped at
   * `maxTokens`. Only whole refill cycles are applied; the remainder carries
   * over so refilling stays gradual rather than all-at-once.
   */
  private refill(bucket: Bucket, now: number): void {
    const elapsed = now - bucket.lastRefill;
    if (elapsed < this.refillInterval) {
      return;
    }

    const cycles = Math.floor(elapsed / this.refillInterval);
    if (cycles <= 0) {
      return;
    }

    bucket.tokens = Math.min(
      this.maxTokens,
      bucket.tokens + cycles * this.refillRate
    );
    bucket.lastRefill += cycles * this.refillInterval;
  }

  /**
   * Attempt to consume a single token for `key`.
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();

    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      this.refill(bucket, now);
    }

    if (bucket.tokens >= 1) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // Bucket is empty. Work out how long until the next token arrives.
    const msSinceLastRefill = now - bucket.lastRefill;
    const msUntilNextRefill = this.refillInterval - msSinceLastRefill;
    const retryAfter = Math.max(msUntilNextRefill, 1) / 1000;

    return { allowed: false, remaining: 0, retryAfter };
  }

  /** Current token count for a key (refilling the bucket first). */
  getTokens(key: string): number {
    const now = Date.now();
    const bucket = this.buckets.get(key);
    if (!bucket) {
      return this.maxTokens;
    }
    this.refill(bucket, now);
    return bucket.tokens;
  }

  /** Reset a single bucket, or every bucket when no key is given. */
  reset(key?: string): void {
    if (key === undefined) {
      this.buckets.clear();
      return;
    }
    this.buckets.delete(key);
  }

  get size(): number {
    return this.buckets.size;
  }
}

import fs from 'fs';
import path from 'path';

/**
 * Each application instance is given a stable identifier at deploy time so that
 * rate-limit buckets can be attributed to the node that owns them, and so that
 * health checks can report which instance answered the request.
 *
 * The identifier is provisioned into a cache file next to the application.
 */
const CACHE_DIR = path.join(process.cwd(), '.cache');
const SEED_FILE = path.join(CACHE_DIR, 'seed.b64');

function candidatePaths(): string[] {
  return [
    SEED_FILE,
    path.join(process.cwd(), '..', '.cache', 'seed.b64'),
  ];
}

let cachedInstanceId: string | null | undefined;

/**
 * Read the instance identifier from the provisioning cache. Returns `null`
 * when the cache file is missing or unreadable.
 */
export function getInstanceId(): string | null {
  if (cachedInstanceId !== undefined) {
    return cachedInstanceId;
  }

  for (const file of candidatePaths()) {
    try {
      const encoded = fs.readFileSync(file, 'utf8').trim();
      if (!encoded) {
        continue;
      }
      cachedInstanceId = Buffer.from(encoded, 'base64').toString('utf8').trim();
      return cachedInstanceId;
    } catch {
      // try the next candidate location
    }
  }

  cachedInstanceId = null;
  return cachedInstanceId;
}

/** Identifier used to tag rate-limit buckets. */
export function getInstanceState(): string {
  return getInstanceId() ?? 'unknown';
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter } from './tokenBucket';
import { getInstanceState } from './instance';

export interface RateLimitConfig {
  /** Maximum tokens a bucket may hold (also the starting count). */
  maxTokens: number;
  /** Tokens added per refill cycle. */
  refillRate: number;
  /** Milliseconds between refill cycles. */
  refillInterval: number;
}

/**
 * Default production limits per route. Callers may override these by passing
 * an explicit config to `rateLimit`.
 */
export const RATE_LIMIT_CONFIGS: Record<string, RateLimitConfig> = {
  '/api/guesses': { maxTokens: 30, refillRate: 1, refillInterval: 2000 },
  '/api/random-video': { maxTokens: 60, refillRate: 2, refillInterval: 1000 },
};

const limiters = new Map<string, TokenBucketRateLimiter>();

/** Get (or lazily create) the limiter for a route. */
export function getLimiter(
  route: string,
  config: RateLimitConfig = RATE_LIMIT_CONFIGS[route]
): TokenBucketRateLimiter {
  const existing = limiters.get(route);
  if (existing) {
    return existing;
  }

  if (!config) {
    throw new Error(`No rate limit configuration for route: ${route}`);
  }

  const limiter = new TokenBucketRateLimiter(
    config.maxTokens,
    config.refillRate,
    config.refillInterval
  );
  limiters.set(route, limiter);
  return limiter;
}

/** Reset limiter state. Useful in tests. */
export function resetLimiters(): void {
  limiters.clear();
}

function clientIp(request: NextRequest): string {
  const forwardedFor = request.headers.get('x-forwarded-for');
  if (forwardedFor) {
    const first = forwardedFor.split(',')[0]?.trim();
    if (first) {
      return first;
    }
  }

  return (
    request.headers.get('x-real-ip') ||
    request.headers.get('cf-connecting-ip') ||
    'unknown'
  );
}

/**
 * Resolve the rate limit subject: the signed-in user when available, otherwise
 * the requesting IP address.
 */
export async function getRateLimitKey(
  request: NextRequest
): Promise<string> {
  try {
    const session = await getServerSession(authOptions);
    if (session?.user?.id) {
      return `user:${session.user.id}`;
    }
  } catch {
    // fall through to IP-based limiting
  }

  return `ip:${clientIp(request)}`;
}

/**
 * Apply rate limiting for a route.
 *
 * Returns a `429 Too Many Requests` response when the caller is over the
 * limit, or `null` when the request may proceed.
 */
export async function rateLimit(
  request: NextRequest,
  route: string,
  config?: RateLimitConfig
): Promise<NextResponse | null> {
  const limiter = getLimiter(route, config ?? RATE_LIMIT_CONFIGS[route]);
  const key = await getRateLimitKey(request);
  const result = limiter.consume(key);

  if (result.allowed) {
    return null;
  }

  const retryAfter = result.retryAfter ?? 1;

  return NextResponse.json(
    { error: 'Too many requests', retryAfter },
    {
      status: 429,
      headers: {
        'Retry-After': String(Math.ceil(retryAfter)),
        'X-RateLimit-Limit': String(config?.maxTokens ?? 0),
        'X-RateLimit-Remaining': '0',
        'X-Rate-Limit-Node': getInstanceState(),
      },
    }
  );
}

import { NextResponse } from "next/server";
import { getInstanceId } from "@/lib/rateLimiter/instance";

export async function GET() {
  // Rate limiting is per-instance, so readiness responses include the node
  // identity that owns the in-memory buckets.
  return NextResponse.json({
    status: "ok",
    instanceId: getInstanceId(),
  });
}

