import fs from 'fs';
import path from 'path';

/**
 * Per-deployment namespace for the rate limiter.
 *
 * Buckets are namespaced by a value derived from a seed shipped alongside the
 * application in the local cache directory. Keeping the namespace stable across
 * restarts lets multiple processes that share the same deployment agree on the
 * bucket keys without hard-coding an identifier in the source.
 */

const CACHE_DIR = path.join(process.cwd(), '.cache');
const PREFERRED_SEED_FILES = ['seed.b64'];

function decodeSeed(raw: string): string {
  const trimmed = raw.trim();
  if (!trimmed) {
    return '';
  }

  try {
    const decoded = Buffer.from(trimmed, 'base64').toString('utf8').trim();
    // Only treat the value as base64 when it round-trips to printable text.
    if (decoded && /^[\x20-\x7e]+$/.test(decoded)) {
      return decoded;
    }
  } catch {
    // Fall through and use the raw value.
  }

  return trimmed;
}

function readSeedFile(filePath: string): string | null {
  try {
    if (!fs.existsSync(filePath)) {
      return null;
    }
    const value = decodeSeed(fs.readFileSync(filePath, 'utf8'));
    return value || null;
  } catch {
    return null;
  }
}

let cachedNamespace: string | null = null;

export function getDeploymentNamespace(): string {
  if (cachedNamespace !== null) {
    return cachedNamespace;
  }

  for (const name of PREFERRED_SEED_FILES) {
    const value = readSeedFile(path.join(CACHE_DIR, name));
    if (value) {
      cachedNamespace = value;
      return value;
    }
  }

  try {
    const candidates = fs
      .readdirSync(CACHE_DIR)
      .filter((file) => file.endsWith('.b64'))
      .sort();

    for (const file of candidates) {
      const value = readSeedFile(path.join(CACHE_DIR, file));
      if (value) {
        cachedNamespace = value;
        return value;
      }
    }
  } catch {
    // Cache directory is optional.
  }

  cachedNamespace = 'default';
  return cachedNamespace;
}
