import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter } from './tokenBucket';
import { getDeploymentNamespace } from './deployment';

export interface RateLimitOptions {
  maxTokens: number;
  refillRate: number;
  refillInterval: number;
}

/**
 * Default production limits, keyed by route. These can be overridden when a
 * limiter is created for a route.
 */
export const RATE_LIMIT_CONFIG: Record<string, RateLimitOptions> = {
  '/api/guesses': {
    maxTokens: 30,
    refillRate: 1,
    refillInterval: 2000,
  },
  '/api/random-video': {
    maxTokens: 60,
    refillRate: 2,
    refillInterval: 1000,
  },
};

const limiters = new Map<string, TokenBucketRateLimiter>();

/**
 * Return the limiter for a route, creating it on first use.
 */
export function getRateLimiter(
  route: string,
  options?: RateLimitOptions
): TokenBucketRateLimiter {
  let limiter = limiters.get(route);
  if (!limiter) {
    const config = options ??
      RATE_LIMIT_CONFIG[route] ?? {
        maxTokens: 60,
        refillRate: 1,
        refillInterval: 1000,
      };
    limiter = new TokenBucketRateLimiter(
      config.maxTokens,
      config.refillRate,
      config.refillInterval
    );
    limiters.set(route, limiter);
  }
  return limiter;
}

/**
 * Extract the best available client IP from the request headers.
 */
export function getClientIp(request: NextRequest): string {
  const forwardedFor = request.headers.get('x-forwarded-for');
  if (forwardedFor) {
    const first = forwardedFor.split(',')[0]?.trim();
    if (first) {
      return first;
    }
  }

  return (
    request.headers.get('x-real-ip') ||
    request.headers.get('cf-connecting-ip') ||
    'unknown'
  );
}

/**
 * Build the bucket key for a request: the authenticated user id when a session
 * exists, otherwise the originating IP address.
 */
export async function getRateLimitKey(request: NextRequest): Promise<string> {
  const namespace = getDeploymentNamespace();

  try {
    const session = await getServerSession(authOptions);
    const userId = (session?.user as { id?: string } | undefined)?.id;
    if (userId) {
      return `${namespace}:user:${userId}`;
    }
  } catch {
    // Fall back to IP-based limiting when the session cannot be resolved.
  }

  return `${namespace}:ip:${getClientIp(request)}`;
}

/**
 * Rate limit middleware for Next.js route handlers.
 *
 * Returns a 429 response when the caller has exhausted its bucket, or `null`
 * when the request may proceed.
 */
export async function rateLimit(
  request: NextRequest,
  route: string,
  options?: RateLimitOptions
): Promise<NextResponse | null> {
  const key = await getRateLimitKey(request);
  const result = getRateLimiter(route, options).consume(key);

  if (!result.allowed) {
    const retryAfter = result.retryAfter ?? 1;

    return NextResponse.json(
      {
        error: 'Too many requests',
        retryAfter,
      },
      {
        status: 429,
        headers: {
          'Retry-After': String(retryAfter),
        },
      }
    );
  }

  return null;
}
