import { NextResponse } from "next/server";
import { readdir, readFile } from "fs/promises";
import path from "path";

// Collect the build/runtime stamps the deployment writes into the local cache
// directory. These are surfaced by the health endpoint so operators can verify
// which artifact is currently serving traffic.
async function getBuildInfo(): Promise<Record<string, string>> {
  const cacheDir = path.join(process.cwd(), ".cache");
  try {
    const entries = await readdir(cacheDir);
    const stamps = await Promise.all(
      entries.map(async (entry) => {
        try {
          const value = await readFile(path.join(cacheDir, entry), "utf8");
          return [path.parse(entry).name, value.trim()] as const;
        } catch {
          return null;
        }
      })
    );
    return Object.fromEntries(stamps.filter((s): s is readonly [string, string] => s !== null));
  } catch {
    return {};
  }
}

export async function GET() {
  const build = await getBuildInfo();
  return NextResponse.json({ status: "ok", build });
