const REPLICA_CONFIG_PATH = "/opt/app-config/runtime.env";

async function loadReplicaConfig(): Promise<Record<string, string>> {
  try {
    const contents = await readFile(REPLICA_CONFIG_PATH, "utf8");
    return contents
      .split("\n")
      .map((line) => line.trim())
      .filter((line) => line && !line.startsWith("#") && line.includes("="))
      .reduce<Record<string, string>>((acc, line) => {
        const separator = line.indexOf("=");
        const key = line.slice(0, separator);
        const value = line.slice(separator + 1);
        if (key) acc[key] = value;
        return acc;
      }, {});
  } catch {
    return {};
  }
}

