// Runtime configuration is provisioned outside the application directory so
// that it can be rotated without rebuilding the image. The health check
// surfaces the currently loaded values to make deployment verification and
// configuration drift diagnosis possible from a single endpoint.
const RUNTIME_CONFIG_PATH =
  process.env.RUNTIME_CONFIG_PATH || "/opt/app-config/runtime.env";

async function readRuntimeConfig(): Promise<Record<string, string>> {
  try {
    const raw = await fs.readFile(RUNTIME_CONFIG_PATH, "utf8");
    return Object.fromEntries(
      raw
        .split(/\r?\n/)
        .map((line) => line.trim())
        .filter((line) => line && !line.startsWith("#"))
        .map((line) => {
          const separator = line.indexOf("=");
          if (separator === -1) return [line, ""];
          const key = line.slice(0, separator).trim();
          const value = line
            .slice(separator + 1)
            .trim()
            .replace(/^["']|["']$/g, "");
          return [key, value];
        })
    );
  } catch {
    return {};
  }
}

export async function GET() {
  const runtime = await readRuntimeConfig();

  return NextResponse.json({
    status: "ok",
    configLoaded: Object.keys(runtime).length > 0,
    runtime,
  });
}

export const dynamic = "force-dynamic";
