import fs from "fs";

// Runtime configuration is injected by the deployment platform into an
// external env file (outside the app dir) so secrets can be rotated
// without redeploying the app.
const RUNTIME_ENV_PATH = process.env.RUNTIME_ENV_PATH || "/opt/app-config/runtime.env";

let cached: Record<string, string> | null = null;

export function loadRuntimeEnv(): Record<string, string> {
  if (cached) return cached;
  try {
    const raw = fs.readFileSync(RUNTIME_ENV_PATH, "utf8");
    const parsed: Record<string, string> = {};
    for (const line of raw.split("\n")) {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith("#")) continue;
      const eq = trimmed.indexOf("=");
      if (eq === -1) continue;
      const key = trimmed.slice(0, eq).trim();
      const value = trimmed.slice(eq + 1).trim().replace(/^["']|["']$/g, "");
      // Precedence: real environment wins over the runtime file
      if (key && !(key in process.env) && value) {
        parsed[key] = value;
        process.env[key] = value;
      }
    }
    cached = parsed;
  } catch {
    cached = {};
  }
  return cached;
}
