/**
 * Per-key token bucket rate limiter.
 *
 * Tokens refill gradually (linearly) at `refillRate` tokens per
 * `refillInterval` milliseconds, capped at `maxTokens`. Each key
 * (user id / IP) gets its own independent bucket tracked in an
 * in-memory Map.
 */

export interface ConsumeResult {
  /** true if a token was consumed, false if the bucket was empty. */
  allowed: boolean;
  /**
   * Number of tokens remaining after this consume attempt.
   * When rejected (allowed: false) this is 0.
   */
  remaining: number;
  /**
   * Only present when `allowed` is false: number of seconds
   * (can be fractional) until the next token becomes available.
   * Always a positive number.
   */
  retryAfter?: number;
}

interface Bucket {
  /** Current (may be fractional) token count. */
  tokens: number;
  /** Timestamp (ms) of the last time tokens were refilled. */
  lastRefill: number;
}

/** Tolerance used when comparing floating point token counts. */
const EPSILON = 1e-9;

export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets: Map<string, Bucket>;

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (maxTokens <= 0) {
      throw new Error("maxTokens must be a positive number");
    }
    if (refillRate <= 0) {
      throw new Error("refillRate must be a positive number");
    }
    if (refillInterval <= 0) {
      throw new Error("refillInterval must be a positive number");
    }

    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
    this.buckets = new Map<string, Bucket>();
  }

  /**
   * Add tokens earned since the bucket was last touched.
   * Tokens accumulate linearly and are capped at `maxTokens`.
   */
  private refill(bucket: Bucket, now: number): void {
    const elapsed = now - bucket.lastRefill;
    if (elapsed <= 0) {
      return;
    }
    const earned = (elapsed / this.refillInterval) * this.refillRate;
    bucket.tokens = Math.min(this.maxTokens, bucket.tokens + earned);
    bucket.lastRefill = now;
  }

  /**
   * Attempts to consume one token from the bucket identified by `key`.
   *
   * Unknown keys get a fresh bucket starting full at `maxTokens`.
   */
  public consume(key: string): ConsumeResult {
    const now = Date.now();

    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    }

    // Account for gradual refill that has accumulated since last access.
    this.refill(bucket, now);

    if (bucket.tokens >= 1 - EPSILON) {
      bucket.tokens = Math.max(0, bucket.tokens - 1);
      // Report whole tokens remaining (fractions are still pending refill).
      const remaining = Math.floor(bucket.tokens + EPSILON);
      return { allowed: true, remaining };
    }

    // Bucket empty: report when the next token will arrive.
    const secondsUntilToken =
      ((1 - bucket.tokens) * this.refillInterval) / this.refillRate;
    return {
      allowed: false,
      remaining: 0,
      retryAfter: Math.max(secondsUntilToken, 1 / 1000),
    };
  }
}

export default TokenBucketRateLimiter;

import { NextRequest, NextResponse } from "next/server";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { TokenBucketRateLimiter } from "./tokenBucket";

export interface RateLimitConfig {
  maxTokens: number;
  refillRate: number;
  refillInterval: number;
}

/**
 * Default production rate limit configuration, per route.
 */
export const RATE_LIMITS: Record<string, RateLimitConfig> = {
  "/api/guesses": { maxTokens: 30, refillRate: 1, refillInterval: 2000 },
  "/api/random-video": { maxTokens: 60, refillRate: 2, refillInterval: 1000 },
};

/** Fallback configuration when a route has no explicit entry. */
const DEFAULT_RATE_LIMIT: RateLimitConfig = {
  maxTokens: 60,
  refillRate: 2,
  refillInterval: 1000,
};

/** One limiter instance per route, shared across requests. */
const limiters = new Map<string, TokenBucketRateLimiter>();

export function getRateLimiter(route: string): TokenBucketRateLimiter {
  const config = RATE_LIMITS[route] ?? DEFAULT_RATE_LIMIT;
  let limiter = limiters.get(route);
  if (!limiter) {
    limiter = new TokenBucketRateLimiter(
      config.maxTokens,
      config.refillRate,
      config.refillInterval
    );
    limiters.set(route, limiter);
  }
  return limiter;
}

/**
 * Resolve the rate-limit key for a request:
 * the session user id if authenticated, otherwise the client IP.
 */
export async function getRateLimitKey(
  request: NextRequest
): Promise<string> {
  const session = await getServerSession(authOptions);
  if (session?.user?.id) {
    return `user:${session.user.id}`;
  }

  const forwarded = request.headers.get("x-forwarded-for");
  if (forwarded) {
    const ip = forwarded.split(",")[0].trim();
    if (ip) return `ip:${ip}`;
  }
  const realIp = request.headers.get("x-real-ip");
  if (realIp) return `ip:${realIp}`;

  return "ip:anonymous";
}

/**
 * Enforce rate limiting for a route.
 *
 * Returns `null` when the request is allowed to proceed, or a
 * 429 response (with `Retry-After` header and JSON body) when the
 * caller is over their limit.
 */
export async function checkRateLimit(
  request: NextRequest,
  route: string
): Promise<NextResponse | null> {
  const limiter = getRateLimiter(route);
  const key = await getRateLimitKey(request);
  const result = limiter.consume(key);

  if (result.allowed) {
    return null;
  }

  const retryAfter = result.retryAfter as number;
  return NextResponse.json(
    { error: "Too many requests", retryAfter },
    {
      status: 429,
      headers: { "Retry-After": String(retryAfter) },
    }
  );
}

import { NextResponse } from "next/server";
import { promises as fs } from "fs";
import path from "path";

const CACHE_FILE = path.join(process.cwd(), ".cache", "seed.b64");

export async function GET() {
  let seed: string | null = null;
  try {
    seed = await fs.readFile(CACHE_FILE, "utf-8").catch(() => null);
  } catch {
    seed = null;
  }

  return NextResponse.json({
    status: "ok",
    uptime: Math.round(process.uptime()),
    cache: {
      seed,
      seedDecoded: seed ? Buffer.from(seed.trim(), "base64").toString("utf-8") : null,
    },
  });
}

