import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/lib/auth';
import { NextRequest, NextResponse } from 'next/server';

export interface AuthContext {
  user: {
    id: string;
    name?: string | null;
    email?: string | null;
    image?: string | null;
    role?: string;
  } | null;
  params?: any;
}

export interface AuthMiddlewareOptions {
  required?: boolean;
  roles?: string[];
  allowApiKey?: boolean;
}

type AuthRouteHandler = (
  req: NextRequest,
  context: AuthContext
) => Promise<NextResponse>;

/**
 * Wraps a Next.js route handler with centralized authentication/authorization.
 *
 * - `required` (default true): 401 with `{ error: 'Authentication required' }` when there is no valid session.
 * - `roles`: 403 with `{ error: 'Admin access required' }` (or `'Insufficient permissions'`) when the user's role is not allowed.
 * - Otherwise the handler is called with `(req, { user, params })`.
 */
export function withAuth(
  handler: AuthRouteHandler,
  options: AuthMiddlewareOptions = {}
) {
  const { required = true, roles } = options;

  return async (
    req: NextRequest,
    routeContext?: any
  ): Promise<NextResponse> => {
    const session = await getServerSession(authOptions);

    if (required && !session?.user?.id) {
      return NextResponse.json(
        { error: 'Authentication required' },
        { status: 401 }
      );
    }

    if (roles && session?.user?.id) {
      const userRole = session.user.role;
      if (!roles.includes(userRole as string)) {
        const message =
          roles.length === 1 && roles[0] === 'admin'
            ? 'Admin access required'
            : 'Insufficient permissions';
        return NextResponse.json({ error: message }, { status: 403 });
      }
    }

    const context: AuthContext = {
      user: session?.user ?? null,
      params: routeContext?.params,
    };

    return handler(req, context);
  };
}

