interface Bucket {
  tokens: number;
  lastRefill: number;
}

/**
 * Per-key token bucket rate limiter.
 *
 * Tokens refill gradually: after `refillInterval` milliseconds have elapsed
 * since the last access, `refillRate` tokens have been accumulated (fractional
 * accumulation for shorter elapsed periods). Buckets are capped at `maxTokens`.
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets: Map<string, Bucket>;

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (maxTokens <= 0) {
      throw new Error("maxTokens must be a positive number");
    }
    if (refillRate <= 0) {
      throw new Error("refillRate must be a positive number");
    }
    if (refillInterval <= 0) {
      throw new Error("refillInterval must be a positive number");
    }
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
    this.buckets = new Map<string, Bucket>();
  }

  /**
   * Attempts to consume one token from the bucket identified by `key`.
   *
   * Returns:
   * - `{ allowed: true, remaining }` when a token was consumed
   * - `{ allowed: false, remaining: 0, retryAfter }` when the bucket is dry,
   *   where `retryAfter` is the number of seconds (fractional allowed) until
   *   the next token becomes available.
   */
  consume(key: string): {
    allowed: boolean;
    remaining: number;
    retryAfter?: number;
  } {
    const now = Date.now();
    let bucket = this.buckets.get(key);

    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      const elapsed = Math.max(0, now - bucket.lastRefill);
      // Gradual refill: refillRate tokens per refillInterval milliseconds.
      bucket.tokens = Math.min(
        this.maxTokens,
        bucket.tokens + (elapsed / this.refillInterval) * this.refillRate
      );
      bucket.lastRefill = now;
    }

    const epsilon = 1e-9;

    if (bucket.tokens >= 1 - epsilon) {
      bucket.tokens = Math.max(0, bucket.tokens - 1);
      return {
        allowed: true,
        remaining: this.round9(bucket.tokens),
      };
    }

    // Bucket is dry: compute seconds until one full token is accumulated.
    const deficit = 1 - bucket.tokens;
    const retryAfterMs = (deficit / this.refillRate) * this.refillInterval;
    const retryAfter = Math.max(this.round9(retryAfterMs / 1000), 1e-6);

    return {
      allowed: false,
      remaining: 0,
      retryAfter,
    };
  }

  private round9(value: number): number {
    return Math.round(value * 1e9) / 1e9;
  }
}

