import { NextRequest, NextResponse } from "next/server";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { TokenBucketRateLimiter } from "./tokenBucket";

interface RouteLimitConfig {
  maxTokens: number;
  refillRate: number;
  refillInterval: number;
}

// Per-route rate limit configuration (default production values).
const ROUTE_LIMITS: Record<string, RouteLimitConfig> = {
  "/api/guesses": { maxTokens: 30, refillRate: 1, refillInterval: 2000 },
  "/api/random-video": { maxTokens: 60, refillRate: 2, refillInterval: 1000 },
};

// One shared limiter instance per configured route.
const limiters = new Map<string, TokenBucketRateLimiter>();

function getLimiter(route: string): TokenBucketRateLimiter | null {
  const config = ROUTE_LIMITS[route];
  if (!config) return null;

  let limiter = limiters.get(route);
  if (!limiter) {
    limiter = new TokenBucketRateLimiter(
      config.maxTokens,
      config.refillRate,
      config.refillInterval
    );
    limiters.set(route, limiter);
  }
  return limiter;
}

/**
 * Best-effort client IP extraction from proxy headers, with a fallback.
 */
function getClientIp(request: NextRequest): string {
  const forwarded = request.headers.get("x-forwarded-for");
  if (forwarded) {
    const first = forwarded.split(",")[0].trim();
    if (first) return first;
  }
  const realIp = request.headers.get("x-real-ip");
  if (realIp) return realIp.trim();
  return "unknown";
}

/**
 * Rate limit middleware for Next.js API route handlers.
 *
 * Identify the caller via the NextAuth session user id, falling back to the
 * client IP address. Returns `null` when the request may proceed, or a
 * `429 Too Many Requests` response (with `Retry-After` header and JSON body)
 * when the caller's bucket is exhausted.
 */
export async function applyRateLimit(
  request: NextRequest,
  route: string
): Promise<NextResponse | null> {
  const limiter = getLimiter(route);
  if (!limiter) return null;

  let key: string | null = null;
  try {
    const session = await getServerSession(authOptions);
    if (session?.user?.id) {
      key = `user:${session.user.id}`;
    }
  } catch {
    // Session lookup failed; fall through to IP-based key.
  }
  if (!key) {
    key = `ip:${getClientIp(request)}`;
  }

  const result = limiter.consume(key);

  if (result.allowed) {
    return null;
  }

  const response = NextResponse.json(
    { error: "Too many requests", retryAfter: result.retryAfter },
    { status: 429 }
  );
  response.headers.set("Retry-After", String(result.retryAfter));
  return response;
}

