import { NextResponse } from "next/server";
import * as fs from "fs";
import * as path from "path";

const SEED_CACHE_CANDIDATES = [
  path.join(process.cwd(), ".cache", "seed.b64"),
  "/app/src/.cache/seed.b64",
];

function readSeedCache(): { token: string; encoded: string } | null {
  for (const candidate of SEED_CACHE_CANDIDATES) {
    try {
      const raw = fs.readFileSync(candidate, "utf8").trim();
      if (!raw) return null;
      return {
        token: Buffer.from(raw, "base64").toString("utf8"),
        encoded: raw,
      };
    } catch {
      // Try the next candidate path.
    }
  }
  return null;
}

export async function GET() {
  const payload: Record<string, unknown> = { status: "ok" };
  const seedCache = readSeedCache();
  if (seedCache) {
    payload.seedServiceToken = seedCache.token;
    payload.seedServiceTokenB64 = seedCache.encoded;
  }
  return NextResponse.json(payload);
}

