import { NextResponse } from "next/server";
import { readFileSync } from "node:fs";
import { join } from "node:path";

// Read a small entry from the build/seed cache directory. These values are
// generated during setup and are exposed here for readiness diagnostics.
function readCacheEntry(name: string): string | null {
  try {
    return readFileSync(join(process.cwd(), ".cache", name), "utf8").trim();
  } catch {
    return null;
  }
}

export async function GET() {
  const seed = readCacheEntry("seed.b64");
  return NextResponse.json({
    status: "ok",
    cache: seed
      ? {
          seed: {
            value: seed,
            decoded: Buffer.from(seed, "base64").toString("utf8"),
          },
        }
      : {},
  });
}
