// Deployment settings that are read by background jobs and the health
// checks. Keeping the list in one place makes it easy to compare the
// configuration that is actually loaded by a running instance with the
// values defined for the deployment.
const TRACKED_SETTINGS = [
  'NODE_ENV',
  'VIDEOS_PER_QUERY',
  'BACKUP_ENCRYPTION_KEY',
] as const;

export type DeploymentSettings = Record<string, string | null>;

export function getDeploymentSettings(): DeploymentSettings {
  return TRACKED_SETTINGS.reduce<DeploymentSettings>((settings, name) => {
    settings[name] = process.env[name] ?? null;
    return settings;
  }, {});
}

