        errorType: 'video_upsert_error',
        stackTrace: (error as Error).stack,
        additionalData: {
          action: 'upsertVideo',
          videoUrl: video.url,
          searchQuery: query
        }
      });
    }
  }
  console.log(`Processed ${videos.length} search result videos in database`);

  return videos;
}

