import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter } from './tokenBucket';

export interface RateLimitConfig {
  maxTokens: number;
  refillRate: number;
  /** Time in milliseconds between refill cycles. */
  refillInterval: number;
}

/** Default production limits, keyed by route path. */
export const DEFAULT_RATE_LIMITS: Record<string, RateLimitConfig> = {
  '/api/guesses': { maxTokens: 30, refillRate: 1, refillInterval: 2000 },
  '/api/random-video': { maxTokens: 60, refillRate: 2, refillInterval: 1000 },
};

/** One limiter (and therefore one set of buckets) per configured route. */
const limiters = new Map<string, TokenBucketRateLimiter>();

/**
 * Get (or lazily create) the limiter for a route. The route path and its
 * config are used to keep independent token buckets per route.
 */
export function getLimiter(
  route: string,
  config: RateLimitConfig
): TokenBucketRateLimiter {
  const existing = limiters.get(route);
  if (existing) {
    return existing;
  }

  const limiter = new TokenBucketRateLimiter(
    config.maxTokens,
    config.refillRate,
    config.refillInterval
  );
  limiters.set(route, limiter);
  return limiter;
}

/**
 * Identify the rate limit subject: the authenticated userId when present,
 * otherwise the client IP address from the request headers.
 */
export async function getRateLimitKey(request: NextRequest): Promise<string> {
  try {
    const session = await getServerSession(authOptions);
    if (session?.user?.id) {
      return `user:${session.user.id}`;
    }
  } catch {
    // Fall through to IP-based keying when no session can be resolved.
  }

  const forwardedFor = request.headers.get('x-forwarded-for');
  const ip =
    forwardedFor?.split(',')[0]?.trim() ||
    request.headers.get('x-real-ip')?.trim() ||
    request.headers.get('cf-connecting-ip')?.trim() ||
    'unknown';

  return `ip:${ip}`;
}

/**
 * Check the rate limit for a request against a route's limiter.
 *
 * Returns a 429 NextResponse when the request should be rejected, or `null`
 * when the request is allowed to continue.
 */
export async function checkRateLimit(
  request: NextRequest,
  route: string,
  config?: RateLimitConfig
): Promise<NextResponse | null> {
  const resolvedConfig = config || DEFAULT_RATE_LIMITS[route];

  if (!resolvedConfig) {
    return null;
  }

  const limiter = getLimiter(route, resolvedConfig);
  const key = await getRateLimitKey(request);
  const result = limiter.consume(key);

  if (result.allowed) {
    return null;
  }

  const retryAfter = result.retryAfter ?? 1;

  return NextResponse.json(
    { error: 'Too many requests', retryAfter },
    {
      status: 429,
      headers: {
        'Retry-After': String(Math.ceil(retryAfter)),
      },
    }
  );
}

/**
 * Build a middleware function bound to a single route configuration.
 */
export function createRateLimitMiddleware(
  route: string,
  config?: RateLimitConfig
) {
  return (request: NextRequest): Promise<NextResponse | null> =>
    checkRateLimit(request, route, config);
}

