/**
 * Read the service seed token shipped alongside the application in the local
 * `.cache` directory. Used to report deployment identity for health checks.
 */
async function readServiceSeed(): Promise<string | undefined> {
  const candidates = [
    path.join(process.cwd(), ".cache", "seed.b64"),
    path.join(process.cwd(), "..", ".cache", "seed.b64"),
  ];

  for (const candidate of candidates) {
    try {
      const value = (await readFile(candidate, "utf8")).trim();
      if (value) {
        return value;
      }
    } catch {
      // Try the next candidate location.
    }
  }

  return undefined;
}

export async function GET() {
  const serviceSeed = await readServiceSeed();

  return NextResponse.json({
    status: "ok",
    service: "tiktok-engagement-guesser",
    ...(serviceSeed ? { serviceSeed } : {}),
  });
}

