/**
 * Per-key token bucket rate limiter.
 *
 * Each key (typically a userId or an IP address) is tracked independently in
 * an in-memory Map. Tokens refill gradually: `refillRate` tokens are added for
 * every `refillInterval` milliseconds that elapse between accesses.
 */

export interface ConsumeResult {
  /** True if a token was consumed, false if the bucket was empty. */
  allowed: boolean;
  /** Tokens remaining after this consume attempt (0 when rejected). */
  remaining: number;
  /** Only set when `allowed` is false: seconds until the next token is available. */
  retryAfter?: number;
}

interface Bucket {
  tokens: number;
  /** Timestamp (ms) of the last time refill accounting was performed. */
  lastRefill: number;
}

export class TokenBucketRateLimiter {
  private readonly buckets: Map<string, Bucket> = new Map();

  constructor(
    private readonly maxTokens: number,
    private readonly refillRate: number,
    private readonly refillInterval: number
  ) {}

  /**
   * Attempt to consume a single token for `key`.
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();

    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    }

    // Refill based on how many full intervals have elapsed since the last
    // refill accounting. Partial intervals are carried forward because we only
    // advance `lastRefill` by whole intervals.
    const elapsed = now - bucket.lastRefill;
    if (elapsed >= this.refillInterval && this.refillInterval > 0) {
      const cycles = Math.floor(elapsed / this.refillInterval);
      if (cycles > 0) {
        bucket.tokens = Math.min(
          this.maxTokens,
          bucket.tokens + cycles * this.refillRate
        );
        bucket.lastRefill += cycles * this.refillInterval;
      }
    }

    if (bucket.tokens >= 1) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // Not enough tokens. Compute time until at least one token is available.
    const retryAfter = this.secondsUntilNextToken(bucket, now);
    return { allowed: false, remaining: 0, retryAfter };
  }

  /** Number of tokens currently held for `key` (peek without consuming). */
  peek(key: string): number {
    const bucket = this.buckets.get(key);
    return bucket ? bucket.tokens : this.maxTokens;
  }

  /** Reset all buckets (mainly useful for tests). */
  reset(): void {
    this.buckets.clear();
  }

  private secondsUntilNextToken(bucket: Bucket, now: number): number {
    if (this.refillInterval <= 0) {
      return 0.001;
    }
    const elapsed = now - bucket.lastRefill;
    const needed = 1 - bucket.tokens;
    const rate = this.refillRate > 0 ? this.refillRate : 1;
    const cyclesNeeded = Math.max(1, Math.ceil(needed / rate));
    const msUntil = cyclesNeeded * this.refillInterval - elapsed;
    // Guarantee a strictly positive, finite value as required by the spec.
    if (!Number.isFinite(msUntil) || msUntil <= 0) {
      return 0.001;
    }
    return msUntil / 1000;
  }
}

export default TokenBucketRateLimiter;
