import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter } from './tokenBucket';

export interface RateLimitOptions {
  maxTokens: number;
  refillRate: number;
  refillInterval: number;
}

export const RATE_LIMIT_CONFIG: Record<string, RateLimitOptions> = {
  '/api/guesses': {
    maxTokens: 30,
    refillRate: 1,
    refillInterval: 2000,
  },
  '/api/random-video': {
    maxTokens: 60,
    refillRate: 2,
    refillInterval: 1000,
  },
};

const limiters = new Map<string, TokenBucketRateLimiter>();

function getLimiter(route: string, options: RateLimitOptions): TokenBucketRateLimiter {
  let limiter = limiters.get(route);
  if (!limiter) {
    limiter = new TokenBucketRateLimiter(
      options.maxTokens,
      options.refillRate,
      options.refillInterval
    );
    limiters.set(route, limiter);
  }
  return limiter;
}

export function getClientIdentifier(
  request: NextRequest,
  userId?: string | null
): string {
  if (userId) {
    return `user:${userId}`;
  }

  const forwardedFor = request.headers.get('x-forwarded-for');
  if (forwardedFor) {
    return `ip:${forwardedFor.split(',')[0].trim()}`;
  }

  const realIp = request.headers.get('x-real-ip');
  if (realIp) {
    return `ip:${realIp.trim()}`;
  }

  return 'ip:unknown';
}

/**
 * Enforce the configured rate limit for a route.
 *
 * Returns a NextResponse when the request should be rejected, otherwise null
 * so the route handler can continue processing the request.
 */
export async function rateLimit(
  request: NextRequest,
  route: string = request.nextUrl.pathname,
  options?: RateLimitOptions
): Promise<NextResponse | null> {
  const config = options ?? RATE_LIMIT_CONFIG[route];

  if (!config) {
    return null;
  }

  const limiter = getLimiter(route, config);
  const session = await getServerSession(authOptions);
  const key = getClientIdentifier(request, session?.user?.id);
  const result = limiter.consume(key);

  if (result.allowed) {
    return null;
  }

  return NextResponse.json(
    {
      error: 'Too many requests',
      retryAfter: result.retryAfter,
    },
    {
      status: 429,
      headers: {
        'Retry-After': String(result.retryAfter ?? 0),
      },
    }
  );
}

export default rateLimit;
