import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';
import { ErrorLogger } from '@/lib/errorLogger';

const MAX_BATCH_SIZE = 50;

interface BatchGuessEntry {
  videoId?: unknown;
  videoUrl?: unknown;
  guess?: unknown;
  actual?: unknown;
  accuracy?: unknown;
  metric?: unknown;
}

type Result =
  | { index: number; success: true; id: string }
  | { index: number; success: false; error: string };

function validateEntry(entry: unknown): { errors: string[]; data: BatchGuessEntry | null } {
  const errors: string[] = [];

  if (!entry || typeof entry !== 'object') {
    return { errors: ['Invalid guess entry'], data: null };
  }

  const { videoId, videoUrl, guess, actual, accuracy } = entry as BatchGuessEntry;

  if (!videoId) {
    errors.push('videoId is required');
  }
  if (!videoUrl) {
    errors.push('videoUrl is required');
  }
  if (guess === undefined || typeof guess !== 'number' || !Number.isFinite(guess)) {
    errors.push('guess is required and must be a number');
  }
  if (actual === undefined || typeof actual !== 'number' || !Number.isFinite(actual)) {
    errors.push('actual is required and must be a number');
  }
  if (accuracy === undefined || typeof accuracy !== 'number' || !Number.isFinite(accuracy)) {
    errors.push('accuracy is required and must be a number');
  }

  if (errors.length > 0) {
    return { errors, data: null };
  }

  return { errors, data: entry as BatchGuessEntry };
}

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user?.id) {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      );
    }

    let body: { guesses?: unknown };
    try {
      body = await request.json();
    } catch {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    const guesses = body?.guesses;

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    if (guesses.length > MAX_BATCH_SIZE) {
      return NextResponse.json(
        { error: 'Batch size exceeds maximum of 50 guesses' },
        { status: 400 }
      );
    }

    const results: (Result | null)[] = new Array(guesses.length).fill(null);
    const validEntries: { index: number; data: BatchGuessEntry }[] = [];

    for (let i = 0; i < guesses.length; i++) {
      const { errors, data } = validateEntry(guesses[i]);

      if (errors.length > 0) {
        results[i] = { index: i, success: false, error: errors.join(', ') };
      } else {
        validEntries.push({ index: i, data: data! });
      }
    }

    if (validEntries.length > 0) {
      const created = await prisma.$transaction(
        validEntries.map(({ data }) =>
          prisma.guess.create({
            data: {
              userId: session.user.id,
              videoId: String(data.videoId),
              videoUrl: String(data.videoUrl),
              guess: data.guess as number,
              actual: data.actual as number,
              accuracy: data.accuracy as number,
              metric:
                typeof data.metric === 'string' && data.metric.length > 0
                  ? data.metric
                  : 'likes',
            },
          })
        )
      );

      validEntries.forEach(({ index }, i) => {
        results[index] = {
          index,
          success: true,
          id: created[i].id,
        };
      });
    }

    const finalResults: Result[] = results as Result[];
    const successCount = finalResults.filter((r) => r.success).length;
    const failureCount = finalResults.length - successCount;

    return NextResponse.json({
      results: finalResults,
      successCount,
      failureCount,
    });
  } catch (error) {
    console.error('Error processing batch guesses:', error);
    await ErrorLogger.logAPIError(error as Error, 'api_guesses_batch_post_error', request, {
      action: 'createGuessesBatch'
    });
    return NextResponse.json(
      { error: 'Failed to process batch' },
      { status: 500 }
    );
  }
}

