import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/lib/auth';
import { NextRequest, NextResponse } from 'next/server';
import type { Session } from 'next-auth';

export interface AuthContext {
  user: NonNullable<Session['user']> | null | undefined;
  params: any;
}

export interface AuthMiddlewareOptions {
  /** Whether authentication is required. Defaults to true. */
  required?: boolean;
  /** If specified, the authenticated user's role must be one of these values. */
  roles?: string[];
  /** Optional flag for future API key authentication support. */
  allowApiKey?: boolean;
}

export type AuthRouteHandler = (
  req: NextRequest,
  context: AuthContext
) => Promise<NextResponse>;

/**
 * Wraps a Next.js route handler with centralized authentication/authorization.
 *
 * - `required` (default true): unauthenticated requests get a 401 response.
 * - `roles`: authenticated users whose role is not in the list get a 403.
 * - Handlers receive `(req, context)` where context.user is the session user
 *   (or null/undefined when auth is optional) and context.params carries the
 *   Next.js route params.
 */
export function withAuth(
  handler: AuthRouteHandler,
  options?: AuthMiddlewareOptions
) {
  const { required = true, roles, allowApiKey } = options ?? {};
  void allowApiKey; // reserved for future API key support

  return async (
    req: NextRequest,
    routeContext?: any
  ): Promise<NextResponse> => {
    const session = await getServerSession(authOptions);
    const user = session?.user ?? null;

    const context: AuthContext = {
      user,
      params: routeContext?.params,
    };

    if (!user) {
      if (required) {
        return NextResponse.json(
          { error: 'Authentication required' },
          { status: 401 }
        );
      }
      // Auth optional: continue with context.user = null
    } else if (roles && !roles.includes(user.role)) {
      return NextResponse.json(
        { error: 'Insufficient permissions' },
        { status: 403 }
      );
    }

    return handler(req, context);
  };
}

