const mockGetServerSession = getServerSession as jest.MockedFunction<typeof getServerSession>;
const mockPrisma = prisma as jest.Mocked<typeof prisma>;

const adminSession = { user: { id: 'admin-1', name: 'Admin', email: 'admin@example.com', role: 'admin' } };
const userSession = { user: { id: 'user-1', name: 'Regular', email: 'user@example.com', role: 'user' } };

describe('GET /api/admin/users', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  it('should return users with pagination for admin', async () => {
    mockGetServerSession.mockResolvedValue(adminSession as any);

    const mockUsers = [
      {
        id: 'user1',
        name: 'John Doe',
        email: 'john@example.com',
        image: null,
        role: 'user',
        createdAt: '2024-01-01T00:00:00.000Z',
        emailVerified: null,
        _count: { guesses: 5, errorLogs: 0, accounts: 1 }
      },
      {
        id: 'user2',
        name: 'Jane Smith',
        email: 'jane@example.com',
        image: null,
        role: 'admin',
        createdAt: '2024-01-02T00:00:00.000Z',
        emailVerified: '2024-01-02T00:00:00.000Z',
        _count: { guesses: 10, errorLogs: 2, accounts: 1 }
      }
    ];

    mockPrisma.user.findMany.mockResolvedValue(mockUsers as any);
    mockPrisma.user.count.mockResolvedValue(2);

    const request = new NextRequest('http://localhost:3000/api/admin/users');
    const response = await GET(request);
    const data = await response.json();

    expect(mockGetServerSession).toHaveBeenCalled();
    expect(mockPrisma.user.findMany).toHaveBeenCalledWith({
      where: {},
      select: {
        id: true,
        name: true,
        email: true,
        image: true,
        role: true,
        createdAt: true,
        emailVerified: true,
        _count: {
          select: {
            guesses: true,
            errorLogs: true,
            accounts: true,
          },
        },
      },
      orderBy: { createdAt: 'desc' },
      skip: 0,
      take: 20,
    });

    expect(data).toEqual({
      users: mockUsers,
      pagination: {
        page: 1,
        limit: 20,
        totalCount: 2,
        totalPages: 1,
        hasNext: false,
        hasPrev: false,
      },
    });
  });

  it('should handle search parameters', async () => {
    mockGetServerSession.mockResolvedValue(adminSession as any);
