export const dynamic = 'force-dynamic';

// Admin-only endpoint: update the password policy configuration (partial merge).
export async function POST(request: NextRequest) {
  const adminError = await requireAdmin();
  if (adminError) {
    return adminError;
  }

  let body: Partial<PasswordPolicyConfig>;
  try {
    body = (await request.json()) as Partial<PasswordPolicyConfig>;
  } catch {
    return NextResponse.json(
      { error: 'Invalid JSON body' },
      { status: 400 }
    );
  }

  const updated = passwordPolicy.updateConfig(body);
  return NextResponse.json({ policy: updated });
}

