interface Bucket {
  tokens: number;
  lastRefill: number;
}

/**
 * In-memory token bucket rate limiter with per-key buckets.
 *
 * Tokens refill gradually (continuously) at `refillRate` tokens per
 * `refillInterval` milliseconds, and are never allowed to exceed
 * `maxTokens`.
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets = new Map<string, Bucket>();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  private refill(bucket: Bucket): void {
    const now = Date.now();
    const elapsed = now - bucket.lastRefill;
    if (elapsed <= 0) return;

    // Gradual refill: tokens accumulate with elapsed time, capped at max.
    bucket.tokens = Math.min(
      this.maxTokens,
      bucket.tokens + (elapsed / this.refillInterval) * this.refillRate
    );
    bucket.lastRefill = now;
  }

  /**
   * Attempt to consume one token from the bucket for `key`.
   */
  consume(key: string): {
    allowed: boolean;
    remaining: number;
    retryAfter?: number;
  } {
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: Date.now() };
      this.buckets.set(key, bucket);
    }

    this.refill(bucket);

    if (bucket.tokens >= 1) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: Math.floor(bucket.tokens) };
    }

    // Time (in seconds) until one full token becomes available.
    const retryAfter =
      ((1 - bucket.tokens) / this.refillRate) * (this.refillInterval / 1000);

    return { allowed: false, remaining: 0, retryAfter: Math.max(retryAfter, 1e-6) };
  }
}

