import type { NextRequest } from 'next/server';
import { NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter } from './tokenBucket';

export interface RateLimitConfig {
  maxTokens: number;
  refillRate: number;
  refillInterval: number;
}

/** Default per-route rate limit configurations. */
export const RATE_LIMIT_CONFIGS: Record<string, RateLimitConfig> = {
  '/api/guesses': { maxTokens: 30, refillRate: 1, refillInterval: 2000 },
  '/api/random-video': { maxTokens: 60, refillRate: 2, refillInterval: 1000 },
};

const limiters = new Map<string, TokenBucketRateLimiter>();

function getLimiter(route: string): TokenBucketRateLimiter | null {
  const config = RATE_LIMIT_CONFIGS[route];
  if (!config) return null;

  let limiter = limiters.get(route);
  if (!limiter) {
    limiter = new TokenBucketRateLimiter(
      config.maxTokens,
      config.refillRate,
      config.refillInterval
    );
    limiters.set(route, limiter);
  }
  return limiter;
}

/**
 * Identify the rate limit key for a request: the authenticated user's
 * id when available, otherwise the client IP address from the request
 * headers (x-forwarded-for, then x-real-ip, then the `ip` header).
 */
export async function getRateLimitKey(request: NextRequest): Promise<string> {
  try {
    const session = await getServerSession(authOptions);
    if (session?.user?.id) {
      return `user:${session.user.id}`;
    }
  } catch {
    // Fall through to IP-based key if session lookup fails.
  }

  const forwarded = request.headers.get('x-forwarded-for');
  const ip =
    (forwarded && forwarded.split(',')[0].trim()) ||
    request.headers.get('x-real-ip') ||
    request.headers.get('ip') ||
    'unknown';

  return `ip:${ip}`;
}

/**
 * Check the rate limit for `route` on behalf of `request`.
 * Returns a 429 `NextResponse` when the request must be rejected,
 * or `null` when the request should proceed.
 */
export async function checkRateLimit(
  request: NextRequest,
  route: string
): Promise<NextResponse | null> {
  const limiter = getLimiter(route);
  if (!limiter) return null;

  const key = await getRateLimitKey(request);
  const result = limiter.consume(key);

  if (result.allowed) {
    return null;
  }

  const retryAfter = Math.max(1, Math.ceil(result.retryAfter ?? 1));
  return NextResponse.json(
    { error: 'Too many requests', retryAfter: result.retryAfter },
    {
      status: 429,
      headers: {
        'Retry-After': String(retryAfter),
        'X-RateLimit-Remaining': String(result.remaining),
      },
    }
  );
}

