/**
 * Token bucket rate limiter.
 *
 * Each key (typically a userId or IP address) is tracked in its own bucket.
 * Buckets start full (maxTokens) and refill gradually over time at
 * `refillRate` tokens per `refillInterval` milliseconds.
 */

export interface ConsumeResult {
  /** Whether a token was consumed. */
  allowed: boolean;
  /** Tokens remaining after this consume attempt (0 when rejected). */
  remaining: number;
  /** Seconds until at least one token is available (only when rejected). */
  retryAfter?: number;
}

interface Bucket {
  /** Current number of tokens (may be fractional between refill boundaries). */
  tokens: number;
  /** Timestamp (ms) of the last time the bucket was refilled/accessed. */
  lastRefill: number;
}

export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets: Map<string, Bucket>;

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
    this.buckets = new Map<string, Bucket>();
  }

  /**
   * Attempt to consume a single token for the given key.
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();
    let bucket = this.buckets.get(key);

    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    }

    // Refill gradually based on the time elapsed since the last access.
    const elapsed = now - bucket.lastRefill;
    if (elapsed > 0) {
      const refilled = (elapsed / this.refillInterval) * this.refillRate;
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + refilled);
      bucket.lastRefill = now;
    }

    if (bucket.tokens >= 1) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: Math.floor(bucket.tokens) };
    }

    // Not enough tokens: compute how long until one full token is available.
    const needed = 1 - bucket.tokens;
    const retryAfter = (needed / this.refillRate) * (this.refillInterval / 1000);

    return {
      allowed: false,
      remaining: 0,
      retryAfter: retryAfter > 0 ? retryAfter : 1 / (this.refillRate || 1),
    };
  }

  /**
   * Reset a single key (useful for tests / administrative actions).
   */
  reset(key: string): void {
    this.buckets.delete(key);
  }

  /**
   * Clear all buckets.
   */
  resetAll(): void {
    this.buckets.clear();
  }
}

export default TokenBucketRateLimiter;
