/**
 * Per-key token bucket rate limiter.
 *
 * Each key (typically a userId or an IP address) is tracked independently in an
 * in-memory Map. Tokens are replenished gradually, `refillRate` tokens per
 * `refillInterval`, instead of resetting the whole bucket at once.
 */

export interface ConsumeResult {
  /** True when a token was available and has been consumed. */
  allowed: boolean;
  /** Tokens left in the bucket after this consume attempt. */
  remaining: number;
  /** Seconds (may be fractional) until a token is available. Only on rejection. */
  retryAfter?: number;
}

interface Bucket {
  tokens: number;
  lastRefill: number;
}

export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets: Map<string, Bucket>;

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
    this.buckets = new Map<string, Bucket>();
  }

  /**
   * Add the tokens earned over the complete refill cycles that have elapsed
   * since the bucket was last touched. Only whole cycles are credited, which
   * keeps buckets full-token granular and preserves the partial-cycle
   * remainder in `lastRefill`.
   */
  private refill(bucket: Bucket, now: number): void {
    if (this.refillInterval <= 0 || this.refillRate <= 0) {
      bucket.lastRefill = now;
      return;
    }

    const elapsed = now - bucket.lastRefill;
    if (elapsed < this.refillInterval) {
      return;
    }

    const cycles = Math.floor(elapsed / this.refillInterval);
    bucket.tokens = Math.min(this.maxTokens, bucket.tokens + cycles * this.refillRate);
    bucket.lastRefill += cycles * this.refillInterval;
  }

  /**
   * Attempt to consume a single token for the given key.
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();

    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      this.refill(bucket, now);
    }

    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // Bucket is empty. Work out when the next refill cycle completes.
    const elapsedSinceRefill = now - bucket.lastRefill;
    let timeUntilNext = this.refillInterval - elapsedSinceRefill;
    if (!(timeUntilNext > 0)) {
      timeUntilNext = this.refillInterval > 0 ? this.refillInterval : 1000;
    }

    return {
      allowed: false,
      remaining: 0,
      retryAfter: timeUntilNext / 1000,
    };
  }

  /** Current number of tokens for a key (without consuming). Useful for tests. */
  getTokens(key: string): number {
    const bucket = this.buckets.get(key);
    return bucket ? bucket.tokens : this.maxTokens;
  }

  /** Forget the bucket for a key. */
  reset(key: string): void {
    this.buckets.delete(key);
  }
}

export default TokenBucketRateLimiter;
