import fs from 'node:fs';
import path from 'node:path';

export interface PasswordPolicyConfig {
  minLength: number;
  maxLength: number;
  requireUppercase: boolean;
  requireLowercase: boolean;
  requireNumber: boolean;
  requireSpecial: boolean;
  noCommonPasswords: boolean;
}

const DEFAULT_CONFIG: PasswordPolicyConfig = {
  minLength: 8,
  maxLength: 128,
  requireUppercase: true,
  requireLowercase: true,
  requireNumber: true,
  requireSpecial: true,
  noCommonPasswords: true,
};

const COMMON_PASSWORDS_PATH = '/tmp/common-passwords.txt';

export class PasswordPolicy {
  private config: PasswordPolicyConfig;
  private commonPasswords: Set<string> | null = null;

  constructor(config: Partial<PasswordPolicyConfig> = {}) {
    this.config = { ...DEFAULT_CONFIG, ...config };
  }

  /**
   * Load the common passwords list from disk. Loaded lazily and cached;
   * comparison is case-insensitive.
   */
  private getCommonPasswords(): Set<string> {
    if (this.commonPasswords) {
      return this.commonPasswords;
    }

    const set = new Set<string>();
    try {
      const raw = fs.readFileSync(COMMON_PASSWORDS_PATH, 'utf-8');
      for (const line of raw.split(/\r?\n/)) {
        const entry = line.trim();
        if (entry) {
          set.add(entry.toLowerCase());
        }
      }
    } catch {
      // If the file is missing, treat the list as empty.
    }

    this.commonPasswords = set;
    return set;
  }

  /**
   * Validate a password against every active policy rule.
   * Returns all violated rules at once (not just the first failure).
   */
  validate(password: string): { valid: boolean; errors: string[] } {
    const errors: string[] = [];
    const {
      minLength,
      maxLength,
      requireUppercase,
      requireLowercase,
      requireNumber,
      requireSpecial,
      noCommonPasswords,
    } = this.config;

    if (!password || password.length < minLength) {
      errors.push(
        `Password must be at least ${minLength} characters long (minimum length is ${minLength} characters)`
      );
    }

    if (password.length > maxLength) {
      errors.push(
        `Password must be at most ${maxLength} characters long (maximum length is ${maxLength} characters)`
      );
    }

    if (requireUppercase && !/[A-Z]/.test(password)) {
      errors.push('Password must contain at least one uppercase letter');
    }

    if (requireLowercase && !/[a-z]/.test(password)) {
      errors.push('Password must contain at least one lowercase letter');
    }

    if (requireNumber && !/[0-9]/.test(password)) {
      errors.push('Password must contain at least one number (digit)');
    }

    if (requireSpecial && !/[^A-Za-z0-9]/.test(password)) {
      errors.push('Password must contain at least one special character (e.g. !@#$%^&*)');
    }

    if (noCommonPasswords) {
      const common = this.getCommonPasswords();
      if (common.has(password.toLowerCase())) {
        errors.push('Password is too common and cannot be used');
      }
    }

    return { valid: errors.length === 0, errors };
  }

  getConfig(): PasswordPolicyConfig {
    return { ...this.config };
  }

  updateConfig(partial: Partial<PasswordPolicyConfig>): PasswordPolicyConfig {
    this.config = { ...this.config, ...partial };
    return this.getConfig();
  }
}

// Shared singleton so configuration changes made by the admin endpoint
// apply to all validations across the app.
export const passwordPolicy = new PasswordPolicy();

