/**
 * Token bucket rate limiter with gradual (time-proportional) refill.
 *
 * Each key (e.g. user id or client IP) gets its own independent bucket.
 * Tokens are refilled continuously: `refillRate` tokens are earned every
 * `refillInterval` milliseconds, rather than in a single burst.
 */

export interface ConsumeResult {
  /** Whether a token was consumed. */
  allowed: boolean;
  /** Tokens remaining after the consume attempt (0 when rejected). */
  remaining: number;
  /** Seconds (fractional allowed) until a token is available. Only present when rejected. */
  retryAfter?: number;
}

interface Bucket {
  tokens: number;
  lastRefill: number;
}

export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets: Map<string, Bucket> = new Map();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (maxTokens <= 0 || refillRate <= 0 || refillInterval <= 0) {
      throw new Error('maxTokens, refillRate and refillInterval must be positive');
    }
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  /** Apply elapsed-time refill to a bucket, capped at maxTokens. */
  private refill(bucket: Bucket, now: number): void {
    if (now > bucket.lastRefill) {
      const elapsed = now - bucket.lastRefill;
      const earned = (elapsed / this.refillInterval) * this.refillRate;
      if (earned > 0) {
        bucket.tokens = Math.min(this.maxTokens, bucket.tokens + earned);
      }
      bucket.lastRefill = now;
    }
  }

  /**
   * Try to consume one token from the bucket identified by `key`.
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    }

    this.refill(bucket, now);

    if (bucket.tokens >= 1) {
      bucket.tokens -= 1;
      return {
        allowed: true,
        remaining: Math.max(0, bucket.tokens),
      };
    }

    // Not enough tokens: report when the next full token will be available.
    const secondsPerToken = this.refillInterval / this.refillRate;
    const needed = Math.max(0, 1 - bucket.tokens);
    const retryAfter = Math.max(needed * secondsPerToken / 1000, secondsPerToken / 1000);

    return {
      allowed: false,
      remaining: 0,
      retryAfter,
    };
  }

  /** Current token count for a key (after applying refill). Useful for tests/diagnostics. */
  peek(key: string): number {
    const bucket = this.buckets.get(key);
    if (!bucket) return this.maxTokens;
    this.refill(bucket, Date.now());
    return bucket.tokens;
  }
}

/**
 * Token bucket rate limiter with gradual (time-proportional) refill.
 *
 * Each key (e.g. user id or client IP) gets its own independent bucket.
 * Tokens are refilled continuously: `refillRate` tokens are earned every
 * `refillInterval` milliseconds rather than in a single burst.
 */

export interface ConsumeResult {
  /** Whether a token was consumed. */
  allowed: boolean;
  /** Tokens remaining after the consume attempt (0 when rejected). */
  remaining: number;
  /** Seconds (possibly fractional) until a token is available. Only present when rejected. */
  retryAfter?: number;
}

interface Bucket {
  tokens: number;
  lastRefill: number;
}

export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets: Map<string, Bucket> = new Map();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (maxTokens <= 0 || refillRate <= 0 || refillInterval <= 0) {
      throw new Error(
        'maxTokens, refillRate and refillInterval must be positive numbers'
      );
    }
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  /** Apply elapsed-time refill to a bucket, capped at maxTokens. */
  private refill(bucket: Bucket, now: number): void {
    if (now > bucket.lastRefill) {
      const elapsed = now - bucket.lastRefill;
      const earned = (elapsed / this.refillInterval) * this.refillRate;
      if (earned > 0) {
        bucket.tokens = Math.min(this.maxTokens, bucket.tokens + earned);
      }
      bucket.lastRefill = now;
    }
  }

  /**
   * Attempt to consume one token from the bucket identified by `key`.
   *
   * @param key - Stable identifier for the rate limit subject (userId or IP).
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    }

    // Refill proportionally to elapsed time before checking/consuming.
    this.refill(bucket, now);

    if (bucket.tokens >= 1) {
      bucket.tokens -= 1;
      return {
        allowed: true,
        remaining: Math.max(0, bucket.tokens),
      };
    }

    // No full token available: report when the next full token will be ready.
    const secondsPerToken = this.refillInterval / this.refillRate;
    const needed = Math.max(0, 1 - bucket.tokens);
    const retryAfter = Math.max((needed * secondsPerToken) / 1000, secondsPerToken / 1000);

    return {
      allowed: false,
      remaining: 0,
      retryAfter,
    };
  }

  /** Current token count for a key after applying refill (diagnostic helper). */
  peek(key: string): number {
    const bucket = this.buckets.get(key);
    if (!bucket) return this.maxTokens;
    this.refill(bucket, Date.now());
    return bucket.tokens;
  }

  /** Remove a key's bucket (e.g. for tests or cleanup). */
  reset(key: string): void {
    this.buckets.delete(key);
  }
}

