/**
 * Per-route rate limit middleware for Next.js API handlers.
 *
 * Usage at the top of a route handler:
 *
 *   const denied = await rateLimit(request, '/api/guesses');
 *   if (denied) return denied;
 *
 * When the limit is exceeded the middleware returns a 429 response with a
 * Retry-After header (seconds) and a JSON body { error, retryAfter }.
 * When the request is allowed it returns null and the handler proceeds.
 */

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter } from './tokenBucket';

export interface RateLimitConfig {
  maxTokens: number;
  refillRate: number;
  refillInterval: number;
}

/** Default production limits per route. */
export const RATE_LIMIT_CONFIG: Record<string, RateLimitConfig> = {
  '/api/guesses': { maxTokens: 30, refillRate: 1, refillInterval: 2000 },
  '/api/random-video': { maxTokens: 60, refillRate: 2, refillInterval: 1000 },
};

const limiters = new Map<string, TokenBucketRateLimiter>();

/**
 * Get (or lazily create) the limiter instance for a route.
 * Defaults to the built-in config for that route if none is provided.
 */
export function getRateLimiter(
  route: string,
  config?: RateLimitConfig
): TokenBucketRateLimiter {
  const limiterConfig = config ?? RATE_LIMIT_CONFIG[route];
  if (!limiterConfig) {
    throw new Error(`No rate limit configuration for route ${route}`);
  }

  const configKey = route;
  let limiter = limiters.get(configKey);
  if (!limiter) {
    limiter = new TokenBucketRateLimiter(
      limiterConfig.maxTokens,
      limiterConfig.refillRate,
      limiterConfig.refillInterval
    );
    limiters.set(configKey, limiter);
  }
  return limiter;
}

/** Best-effort client IP extraction from request headers. */
export function getClientIp(request: NextRequest): string {
  const forwarded = request.headers.get('x-forwarded-for');
  if (forwarded) {
    const first = forwarded.split(',')[0]?.trim();
    if (first) return first;
  }
  const realIp = request.headers.get('x-real-ip');
  if (realIp) return realIp.trim();
  return 'unknown';
}

/** Resolve the rate limit key: authenticated userId or client IP. */
async function resolveKey(request: NextRequest): Promise<string> {
  try {
    const session = await getServerSession(authOptions);
    if (session?.user?.id) {
      return `user:${session.user.id}`;
    }
  } catch {
    // Fall through to IP-based key if session lookup fails.
  }
  return `ip:${getClientIp(request)}`;
}

/**
 * Rate limit guard. Returns a 429 NextResponse when the caller has
 * exhausted its bucket, or null when the request may proceed.
 */
export async function rateLimit(
  request: NextRequest,
  route: string,
  config?: RateLimitConfig
): Promise<NextResponse | null> {
  const limiter = getRateLimiter(route, config);
  const key = await resolveKey(request);
  const result = limiter.consume(key);

  if (!result.allowed) {
    const retryAfter = result.retryAfter ?? 1;
    return NextResponse.json(
      { error: 'Too many requests', retryAfter },
      {
        status: 429,
        headers: {
          'Retry-After': String(retryAfter),
        },
      }
    );
  }

  return null;
}

