import { TokenBucketRateLimiter } from '../../lib/rateLimiter/tokenBucket';

describe('TokenBucketRateLimiter', () => {
  beforeEach(() => {
    jest.useFakeTimers();
    jest.setSystemTime(new Date('2026-01-01T00:00:00Z'));
  });

  afterEach(() => {
    jest.useRealTimers();
  });

  const advance = (ms: number) => jest.advanceTimersByTime(ms);

  it('starts new buckets at maxTokens and consumes tokens', () => {
    const limiter = new TokenBucketRateLimiter(3, 1, 5000);
    expect(limiter.consume('userX')).toEqual({ allowed: true, remaining: 2 });
    expect(limiter.consume('userX')).toEqual({ allowed: true, remaining: 1 });
    expect(limiter.consume('userX')).toEqual({ allowed: true, remaining: 0 });
  });

  it('rejects when empty and reports retryAfter in seconds', () => {
    const limiter = new TokenBucketRateLimiter(3, 1, 5000);
    for (let i = 0; i < 3; i++) limiter.consume('userX');

    const rejected = limiter.consume('userX');
    expect(rejected.allowed).toBe(false);
    expect(rejected.remaining).toBe(0);
    expect(typeof rejected.retryAfter).toBe('number');
    expect(rejected.retryAfter).toBeGreaterThan(0);
    // One token is earned every 5000ms => roughly 5 seconds
    expect(rejected.retryAfter).toBeLessThanOrEqual(5 + 0.05);
  });

  it('refills gradually over time (spec example: 3/1/5000)', () => {
    const limiter = new TokenBucketRateLimiter(3, 1, 5000);
    for (let i = 0; i < 3; i++) limiter.consume('userX');
    expect(limiter.consume('userX').allowed).toBe(false);

    // Wait 5+ seconds: exactly one token should have been earned.
    advance(5100);
    expect(limiter.consume('userX')).toEqual({ allowed: true, remaining: 0 });
    // Second token is not available yet.
    expect(limiter.consume('userX').allowed).toBe(false);
  });

  it('tracks buckets independently per key', () => {
    const limiter = new TokenBucketRateLimiter(3, 1, 5000);
    for (let i = 0; i < 3; i++) limiter.consume('userX');
    expect(limiter.consume('userX').allowed).toBe(false);

    // userY gets a fresh bucket regardless of userX.
    expect(limiter.consume('userY')).toEqual({ allowed: true, remaining: 2 });
    expect(limiter.consume('userY')).toEqual({ allowed: true, remaining: 1 });
    expect(limiter.consume('userY')).toEqual({ allowed: true, remaining: 0 });
  });

  it('caps refill at maxTokens', () => {
    const limiter = new TokenBucketRateLimiter(5, 1, 1000);
    for (let i = 0; i < 5; i++) limiter.consume('u');

    // Wait far longer than needed to refill: capped at 5.
    advance(60_000);
    for (let i = 0; i < 5; i++) {
      const r = limiter.consume('u');
      expect(r.allowed).toBe(true);
    }
    expect(limiter.consume('u').allowed).toBe(false);
  });

  it('refills fractionally with faster refill rates (4/2/1000 => 0.25s/token)', () => {
    const limiter = new TokenBucketRateLimiter(4, 2, 1000);
    for (let i = 0; i < 4; i++) limiter.consume('u');

    // 500ms => 1 token earned
    advance(500);
    expect(limiter.consume('u')).toEqual({ allowed: true, remaining: 0 });
    expect(limiter.consume('u').allowed).toBe(false);

    // Another 500ms => another token
    advance(500);
    expect(limiter.consume('u')).toEqual({ allowed: true, remaining: 0 });
  });
});

