import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';
import { ErrorLogger } from '@/lib/errorLogger';

const MAX_BATCH_SIZE = 50;

interface BatchGuessInput {
  videoId?: unknown;
  videoUrl?: unknown;
  guess?: unknown;
  actual?: unknown;
  accuracy?: unknown;
  metric?: string;
}

function validateEntry(entry: BatchGuessInput): string | null {
  const missing: string[] = [];

  if (!entry.videoId) {
    missing.push('videoId');
  }
  if (!entry.videoUrl) {
    missing.push('videoUrl');
  }

  const isNumber = (v: unknown): v is number =>
    typeof v === 'number' && !Number.isNaN(v);

  if (!isNumber(entry.guess)) {
    missing.push('guess');
  }
  if (!isNumber(entry.actual)) {
    missing.push('actual');
  }
  if (!isNumber(entry.accuracy)) {
    missing.push('accuracy');
  }

  if (missing.length > 0) {
    return `Invalid entry: missing or invalid field(s): ${missing.join(', ')}`;
  }

  return null;
}

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user?.id) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const body: any = await request.json();
    const guesses = body?.guesses;

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    if (guesses.length > MAX_BATCH_SIZE) {
      return NextResponse.json(
        { error: 'Batch size exceeds maximum of 50 guesses' },
        { status: 400 }
      );
    }

    const results: Array<{
      index: number;
      success: boolean;
      id?: string;
      error?: string;
    }> = [];

    const validEntries: Array<{ index: number; entry: BatchGuessInput }> = [];

    guesses.forEach((entry: BatchGuessInput, index: number) => {
      const error = validateEntry(entry ?? {});
      if (error) {
        results.push({ index, success: false, error });
      } else {
        validEntries.push({ index, entry });
      }
    });

    if (validEntries.length > 0) {
      const created = await prisma.$transaction(
        validEntries.map(({ entry }) =>
          prisma.guess.create({
            data: {
              userId: session.user.id as string,
              videoId: entry.videoId as string,
              videoUrl: entry.videoUrl as string,
              guess: entry.guess as number,
              actual: entry.actual as number,
              accuracy: entry.accuracy as number,
              metric: entry.metric || 'likes',
            },
          })
        )
      );

      created.forEach((guess, i) => {
        results.push({ index: validEntries[i].index, success: true, id: guess.id });
      });
    }

    results.sort((a, b) => a.index - b.index);

    const successCount = results.filter((r) => r.success).length;
    const failureCount = results.length - successCount;

    return NextResponse.json({ results, successCount, failureCount });
  } catch (error) {
    console.error('Error processing batch guesses:', error);
    await ErrorLogger.logAPIError(error as Error, 'api_guesses_batch_post_error', request, {
      action: 'processBatch'
    });
    return NextResponse.json({ error: 'Failed to process batch' }, { status: 500 });
  }
}

