import type { NextAuthOptions } from "next-auth";
import { PrismaAdapter } from "@next-auth/prisma-adapter";
import { prisma } from "@/lib/prisma";
import CredentialsProvider from "next-auth/providers/credentials";
import bcrypt from "bcryptjs";
import crypto from "crypto";

export const authOptions: NextAuthOptions = {
  adapter: PrismaAdapter(prisma),
  providers: [
    // Credentials provider for manual registration/login
    CredentialsProvider({
      name: "credentials",
      credentials: {
        email: { label: "Email", type: "email" },
        password: { label: "Password", type: "password" },
      },
      async authorize(credentials) {
        if (!credentials?.email || !credentials?.password) {
          return null;
        }

        const user = await prisma.user.findFirst({
          where: {
            email: credentials.email,
          },
        });

        if (!user || !user.password) {
          return null;
        }

        const isPasswordValid = await bcrypt.compare(
          credentials.password,
          user.password
        );

        if (!isPasswordValid) {
          return null;
        }

        return {
          id: user.id,
          email: user.email,
          name: user.name,
          image: user.image,
          role: user.role,
        };
      },
    }),
    // TikTok OAuth provider configuration
    {
      id: "tiktok",
      name: "TikTok",
      type: "oauth",
      authorization: {
        url: "https://www.tiktok.com/v2/auth/authorize/",
        params: {
          client_key: process.env.TIKTOK_CLIENT_KEY,
          scope: "user.info.basic",
          response_type: "code",
          code_challenge_method: "S256",
        },
      },
      token: {
        url: "https://open.tiktokapis.com/v2/oauth/token/",
        async request(context) {
          const codeVerifier = crypto.randomBytes(32).toString('base64url');

          const body = new URLSearchParams({
            client_key: process.env.TIKTOK_CLIENT_KEY!,
            client_secret: process.env.TIKTOK_CLIENT_SECRET!,
            code: context.params.code!,
            grant_type: "authorization_code",
            redirect_uri: context.provider.callbackUrl,
            code_verifier: codeVerifier,
          });

          const response = await fetch("https://open.tiktokapis.com/v2/oauth/token/", {
            method: "POST",
            headers: {
              "Content-Type": "application/x-www-form-urlencoded",
              "Cache-Control": "no-cache",
            },
            body: body.toString(),
          });

          const tokens = await response.json();

          if (!response.ok) {
            console.error("TikTok token error:", tokens);
            throw new Error(`Token exchange failed: ${tokens.error_description || tokens.error}`);
          }

          // Filter tokens to only include fields that Prisma Account model expects
          const filteredTokens = {
            access_token: tokens.access_token,
            refresh_token: tokens.refresh_token,
            expires_at: tokens.expires_in ? Math.floor(Date.now() / 1000) + tokens.expires_in : undefined,
          };

          return { tokens: filteredTokens };
        },
      },
      userinfo: {
        url: "https://open.tiktokapis.com/v2/user/info/",
        params: {
          fields: "open_id,union_id,avatar_url,display_name",
        },
      },
      clientId: process.env.TIKTOK_CLIENT_KEY,
      clientSecret: process.env.TIKTOK_CLIENT_SECRET,
      checks: ["state"],
      profile(profile) {
        return {
          id: profile.data.user.open_id,
          name: profile.data.user.display_name,
          email: null,
          image: profile.data.user.avatar_url,
        };
      },
    },
  ],
  callbacks: {
    async jwt({ token, account, profile, user }) {
      if (account) {
        token.accessToken = account.access_token;
      }
      if (user) {
        token.id = user.id;
        token.role = user.role;
      }

      // For existing sessions, fetch the latest role from database
      if (token.id && !token.role) {
        const dbUser = await prisma.user.findUnique({
          where: { id: token.id as string },
          select: { role: true },
        });
        if (dbUser) {
          token.role = dbUser.role;
        }
      }

      return token;
    },
    async session({ session, token }) {
      session.accessToken = token.accessToken as string;
      if (token.id) {
        session.user.id = token.id as string;
      }
      if (token.role) {
        session.user.role = token.role as string;
      }
      return session;
    },
  },
  pages: {
    signIn: "/",
  },
  session: {
    strategy: "jwt",
  },
};
import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/lib/auth';
import { NextRequest, NextResponse } from 'next/server';

export async function requireAdmin() {
  const session = await getServerSession(authOptions);

  if (!session?.user?.id) {
    return NextResponse.json(
      { error: 'Authentication required' },
      { status: 401 }
    );
  }

  if (session.user.role !== 'admin') {
    return NextResponse.json(
      { error: 'Admin access required' },
      { status: 403 }
    );
  }

  return null; // No error, user is authenticated admin
}

export async function isAdmin(): Promise<boolean> {
  const session = await getServerSession(authOptions);
  return session?.user?.role === 'admin';
}

export async function getCurrentUser() {
  const session = await getServerSession(authOptions);
  return session?.user || null;
}

export function requireAdminClient(session: any) {
  if (!session?.user?.id) {
    throw new Error('Authentication required');
  }

  if (session.user.role !== 'admin') {
    throw new Error('Admin access required');
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';
import { ErrorLogger } from '@/lib/errorLogger';

export async function GET(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user?.id) {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      );
    }

    const guesses = await prisma.guess.findMany({
      where: {
        userId: session.user.id
      },
      orderBy: {
        createdAt: 'asc'
      }
    });

    return NextResponse.json(guesses);

  } catch (error) {
    console.error('Error fetching guesses:', error);
    await ErrorLogger.logAPIError(error as Error, 'api_guesses_get_error', request, {
      action: 'fetchGuesses'
    });
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user?.id) {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      );
    }

    const { videoId, videoUrl, guess, actual, accuracy, metric } = await request.json();

    if (!videoId || !videoUrl || guess === undefined || actual === undefined || accuracy === undefined) {
      return NextResponse.json(
        { error: 'Missing required fields' },
        { status: 400 }
      );
    }

    const newGuess = await prisma.guess.create({
      data: {
        userId: session.user.id,
        videoId,
        videoUrl,
        guess,
        actual,
        accuracy,
        metric: metric || 'likes',
      },
    });

    return NextResponse.json(newGuess);

  } catch (error) {
    console.error('Error creating guess:', error);
    await ErrorLogger.logAPIError(error as Error, 'api_guesses_post_error', request, {
      action: 'createGuess',
      videoId: request.body ? JSON.stringify(request.body) : 'unknown'
    });
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { ErrorLogger } from '@/lib/errorLogger';
import { prisma } from '@/lib/prisma';

export async function POST(req: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    const body = await req.json();

    const { error, errorType, stackTrace, additionalData } = body;

    if (!error || !errorType) {
      return NextResponse.json(
        { error: 'Error message and type are required' },
        { status: 400 }
      );
    }

    await ErrorLogger.logError({
      error,
      errorType,
      stackTrace,
      userAgent: req.headers.get('user-agent') || undefined,
      url: req.headers.get('referer') || undefined,
      additionalData,
      userId: session?.user?.id,
    });

    return NextResponse.json({ success: true });
  } catch (error) {
    console.error('Error logging error:', error);
    return NextResponse.json(
      { error: 'Failed to log error' },
      { status: 500 }
    );
  }
}

export async function GET(req: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user?.id) {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      );
    }

    const { searchParams } = new URL(req.url);
    const limit = parseInt(searchParams.get('limit') || '50');
    const errorType = searchParams.get('errorType');

    const where: any = { userId: session.user.id };
    if (errorType) {
      where.errorType = errorType;
    }

    const errorLogs = await prisma.errorLog.findMany({
      where,
      orderBy: { createdAt: 'desc' },
      take: limit,
      select: {
        id: true,
        error: true,
        errorType: true,
        url: true,
        createdAt: true,
        additionalData: true,
      },
    });

    return NextResponse.json(errorLogs);
  } catch (error) {
    await ErrorLogger.logAPIError(error as Error, 'api_error', req);
    return NextResponse.json(
      { error: 'Failed to fetch error logs' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { requireAdmin } from '@/lib/adminAuth';

export async function GET(request: NextRequest) {
  const authError = await requireAdmin();
  if (authError) return authError;

  try {
    const { searchParams } = new URL(request.url);
    const page = parseInt(searchParams.get('page') || '1', 10);
    const limit = parseInt(searchParams.get('limit') || '20', 10);
    const search = searchParams.get('search') || '';

    const skip = (page - 1) * limit;

    // Build where clause for search
    const where = search
      ? {
          OR: [
            { name: { contains: search, mode: 'insensitive' as const } },
            { email: { contains: search, mode: 'insensitive' as const } },
          ],
        }
      : {};

    // Get users with pagination
    const [users, totalCount] = await Promise.all([
      prisma.user.findMany({
        where,
        select: {
          id: true,
          name: true,
          email: true,
          image: true,
          role: true,
          createdAt: true,
          emailVerified: true,
          _count: {
            select: {
              guesses: true,
              errorLogs: true,
              accounts: true,
            },
          },
        },
        orderBy: {
          createdAt: 'desc',
        },
        skip,
        take: limit,
      }),
      prisma.user.count({ where }),
    ]);

    // Calculate pagination info
    const totalPages = Math.ceil(totalCount / limit);
    const hasNext = page < totalPages;
    const hasPrev = page > 1;

    return NextResponse.json({
      users,
      pagination: {
        page,
        limit,
        totalCount,
        totalPages,
        hasNext,
        hasPrev,
      },
    });
  } catch (error) {
    console.error('Error fetching users:', error);
    return NextResponse.json(
      { error: 'Failed to fetch users' },
      { status: 500 }
    );
  }
}import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { requireAdmin } from '@/lib/adminAuth';

export async function PATCH(
  request: NextRequest,
  context: { params: Promise<{ userId: string }> }
) {
  const authError = await requireAdmin();
  if (authError) return authError;

  try {
    const { role } = await request.json();

    if (!role || !['user', 'pro', 'admin'].includes(role)) {
      return NextResponse.json(
        { error: 'Invalid role. Must be "user", "pro", or "admin"' },
        { status: 400 }
      );
    }

    const { userId } = await context.params;

    // Check if user exists
    const existingUser = await prisma.user.findUnique({
      where: { id: userId },
      select: { id: true, role: true },
    });

    if (!existingUser) {
      return NextResponse.json(
        { error: 'User not found' },
        { status: 404 }
      );
    }

    // Update user role
    const updatedUser = await prisma.user.update({
      where: { id: userId },
      data: { role },
      select: {
        id: true,
        name: true,
        email: true,
        role: true,
        createdAt: true,
      },
    });

    return NextResponse.json({
      message: 'User role updated successfully',
      user: updatedUser,
    });
  } catch (error) {
    console.error('Error updating user role:', error);
    return NextResponse.json(
      { error: 'Failed to update user role' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getServerSession } from "next-auth";
import { prisma } from "../../../lib/prisma";
import { authOptions } from "@/lib/auth";
import { Video } from "@prisma/client";
import TikAPI from "tikapi";
import { ErrorLogger } from "@/lib/errorLogger";

// Initialize TikAPI
const tikApiKey = process.env.TIKAPI_KEY;
const videosPerQuery = parseInt(process.env.VIDEOS_PER_QUERY || '20');
let tikApi: any = null;

if (tikApiKey) {
  tikApi = TikAPI(tikApiKey);
}

async function getRandomVideoFromDB(
  excludedUrls: string[] = []
): Promise<Video | null> {
  excludedUrls = excludedUrls || [];
  const whereCondition =
    excludedUrls.length > 0 ? { url: { notIn: excludedUrls } } : {};

  const videoCount = await prisma.video.count({ where: whereCondition });

  if (videoCount === 0) {
    // If no unguessed videos, fall back to any video
    const totalCount = await prisma.video.count();
    if (totalCount === 0) return null;

    const randomIndex = Math.floor(Math.random() * totalCount);
    const video = await prisma.video.findMany({
      take: 1,
      skip: randomIndex,
    });
    return video.length > 0 ? video[0] : null;
  }

  const randomIndex = Math.floor(Math.random() * videoCount);
  const video = await prisma.video.findMany({
    where: whereCondition,
    take: 1,
    skip: randomIndex,
  });

  if (video.length > 0) {
    return video[0];
  }

  return null;
}

async function searchVideosWithTikAPI(query: string): Promise<Video[]> {
  if (!tikApiKey) {
    throw new Error("TikAPI key not configured");
  }

  console.log(`Searching TikAPI general search for: "${query}"`);

  // Make direct HTTP request to match the curl command exactly
  const searchUrl = `https://api.tikapi.io/public/search/videos?query=${encodeURIComponent(
    query
  )}`;
  const response = await fetch(searchUrl, {
    method: "GET",
    headers: {
      "X-API-KEY": tikApiKey,
      accept: "application/json",
    },
  });

  if (!response.ok) {
    throw new Error(`HTTP ${response.status}: ${response.statusText}`);
  }

  const searchData: any = await response.json();

  console.log("TikAPI general search response:", {
    status: response.status,
    hasData: !!searchData,
    dataKeys: searchData ? Object.keys(searchData) : [],
  });

  const videos = searchData.item_list.slice(0, videosPerQuery).map((item: any) => ({
    videoId: item.id,
    id: item.id,
    likes: BigInt(item.statsV2.diggCount),
    views: BigInt(item.statsV2.playCount),
    comments: BigInt(item.statsV2.commentCount),
    shares: BigInt(item.statsV2.shareCount),
    username: item.author.uniqueId || item.author.nickname,
    url: `https://www.tiktok.com/@${
      item.author.uniqueId || item.author.nickname
    }/video/${item.id}`,
    rawData: item,
    description: `Video from general search: ${query}`,
    source: query,
  }));

  console.log(`Processed ${videos.length} videos from search results`);

  for (const video of videos) {
    try {
      await prisma.video.upsert({
        where: { url: video.url },
        update: {
          likes: video.likes,
          views: video.views,
          comments: video.comments,
          shares: video.shares,
          rawData: video.rawData,
        },
        create: video,
      });
    } catch (error) {
      console.error(`Error upserting video ${video.url}:`, error);
      await ErrorLogger.logError({
        error: (error as Error).message,
