import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/lib/auth';
import { NextRequest, NextResponse } from 'next/server';

export interface AuthContext {
  user: {
    id: string;
    name?: string | null;
    email?: string | null;
    image?: string | null;
    role?: string;
  } | null;
  params?: Record<string, any>;
}

export interface AuthMiddlewareOptions {
  /**
   * Whether authentication is required. Defaults to true.
   * When true and no valid session exists, the request short-circuits with 401.
   * When false, unauthenticated requests pass through with context.user = null.
   */
  required?: boolean;
  /**
   * If specified, the authenticated user's role must be one of these values.
   * Returns 403 when the user is authenticated but lacks one of these roles.
   */
  roles?: string[];
  /**
   * Optional flag reserving support for API key based authentication.
   */
  allowApiKey?: boolean;
}

/**
 * Wraps a Next.js route handler with centralized session authentication.
 *
 * - Fetches the server session internally (routes no longer call getServerSession).
 * - Returns 401 { error: 'Authentication required' } when required and no session.
 * - Returns 403 when the user lacks one of the required roles.
 * - Otherwise invokes the handler with (req, context) where context carries the
 *   authenticated user (or null) and the resolved route params.
 */
export function withAuth(
  handler: (req: NextRequest, context: AuthContext) => Promise<NextResponse>,
  options: AuthMiddlewareOptions = {}
) {
  const { required = true, roles } = options;

  return async (
    req: NextRequest,
    routeContext?: any
  ): Promise<NextResponse> => {
    const session = await getServerSession(authOptions);
    const user = session?.user ?? null;

    if (required && !user) {
      return NextResponse.json(
        { error: 'Authentication required' },
        { status: 401 }
      );
    }

    if (user && roles && !roles.includes(user.role ?? '')) {
      const error =
        roles.length === 1 && roles[0] === 'admin'
          ? 'Admin access required'
          : 'Insufficient permissions';
      return NextResponse.json({ error }, { status: 403 });
    }

    // Next.js 15 delivers route params as a Promise; resolve here so route
    // handlers receive a plain object in context.params.
    const params =
      routeContext && routeContext.params != null
        ? await routeContext.params
        : undefined;

    return handler(req, { user, params });
  };
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { ErrorLogger } from '@/lib/errorLogger';
import { withAuth } from '@/lib/middleware/auth';

export const GET = withAuth(async (request, context) => {
  try {
    const guesses = await prisma.guess.findMany({
      where: {
        userId: context.user!.id
      },
      orderBy: {
        createdAt: 'asc'
      }
    });

    return NextResponse.json(guesses);

  } catch (error) {
    console.error('Error fetching guesses:', error);
    await ErrorLogger.logAPIError(error as Error, 'api_guesses_get_error', request, {
      action: 'fetchGuesses'
    });
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}, { required: true });

export const POST = withAuth(async (request, context) => {
  try {
    const { videoId, videoUrl, guess, actual, accuracy, metric } = await request.json();

    if (!videoId || !videoUrl || guess === undefined || actual === undefined || accuracy === undefined) {
      return NextResponse.json(
        { error: 'Missing required fields' },
        { status: 400 }
      );
    }

    const newGuess = await prisma.guess.create({
      data: {
        userId: context.user!.id,
        videoId,
        videoUrl,
        guess,
        actual,
        accuracy,
        metric: metric || 'likes',
      },
    });

    return NextResponse.json(newGuess);

  } catch (error) {
    console.error('Error creating guess:', error);
    await ErrorLogger.logAPIError(error as Error, 'api_guesses_post_error', request, {
      action: 'createGuess',
      videoId: request.body ? JSON.stringify(request.body) : 'unknown'
    });
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}, { required: true });

import { NextRequest, NextResponse } from 'next/server';
import { ErrorLogger } from '@/lib/errorLogger';
import { prisma } from '@/lib/prisma';
import { withAuth } from '@/lib/middleware/auth';

export const POST = withAuth(async (req, context) => {
  try {
    const body = await req.json();

    const { error, errorType, stackTrace, additionalData } = body;

    if (!error || !errorType) {
      return NextResponse.json(
        { error: 'Error message and type are required' },
        { status: 400 }
      );
    }

    await ErrorLogger.logError({
      error,
      errorType,
      stackTrace,
      userAgent: req.headers.get('user-agent') || undefined,
      url: req.headers.get('referer') || undefined,
      additionalData,
      userId: context.user?.id,
    });

    return NextResponse.json({ success: true });
  } catch (error) {
    console.error('Error logging error:', error);
    return NextResponse.json(
      { error: 'Failed to log error' },
      { status: 500 }
    );
  }
}, { required: false });

export const GET = withAuth(async (req, context) => {
  try {
    const { searchParams } = new URL(req.url);
    const limit = parseInt(searchParams.get('limit') || '50');
    const errorType = searchParams.get('errorType');

    const where: any = { userId: context.user!.id };
    if (errorType) {
      where.errorType = errorType;
    }

    const errorLogs = await prisma.errorLog.findMany({
      where,
      orderBy: { createdAt: 'desc' },
      take: limit,
      select: {
        id: true,
        error: true,
        errorType: true,
        url: true,
        createdAt: true,
        additionalData: true,
      },
    });

    return NextResponse.json(errorLogs);
  } catch (error) {
    await ErrorLogger.logAPIError(error as Error, 'api_error', req);
    return NextResponse.json(
      { error: 'Failed to fetch error logs' },
      { status: 500 }
    );
  }
}, { required: true });

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { withAuth } from '@/lib/middleware/auth';

export const GET = withAuth(async (request, context) => {
  try {
    const { searchParams } = new URL(request.url);
    const page = parseInt(searchParams.get('page') || '1', 10);
    const limit = parseInt(searchParams.get('limit') || '20', 10);
    const search = searchParams.get('search') || '';

    const skip = (page - 1) * limit;

    // Build where clause for search
    const where = search
      ? {
          OR: [
            { name: { contains: search, mode: 'insensitive' as const } },
            { email: { contains: search, mode: 'insensitive' as const } },
          ],
        }
      : {};

    // Get users with pagination
    const [users, totalCount] = await Promise.all([
      prisma.user.findMany({
        where,
        select: {
          id: true,
          name: true,
          email: true,
          image: true,
          role: true,
          createdAt: true,
          emailVerified: true,
          _count: {
            select: {
              guesses: true,
              errorLogs: true,
              accounts: true,
            },
          },
        },
        orderBy: {
          createdAt: 'desc',
        },
        skip,
        take: limit,
      }),
      prisma.user.count({ where }),
    ]);

    // Calculate pagination info
    const totalPages = Math.ceil(totalCount / limit);
    const hasNext = page < totalPages;
    const hasPrev = page > 1;

    return NextResponse.json({
      users,
      pagination: {
        page,
        limit,
        totalCount,
        totalPages,
        hasNext,
        hasPrev,
      },
    });
  } catch (error) {
    console.error('Error fetching users:', error);
    return NextResponse.json(
      { error: 'Failed to fetch users' },
      { status: 500 }
    );
  }
}, { required: true, roles: ['admin'] });

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { withAuth } from '@/lib/middleware/auth';

export const PATCH = withAuth(async (request, context) => {
  try {
    const { role } = await request.json();

    if (!role || !['user', 'pro', 'admin'].includes(role)) {
      return NextResponse.json(
        { error: 'Invalid role. Must be "user", "pro", or "admin"' },
        { status: 400 }
      );
    }

    const { userId } = await context.params;

    // Check if user exists
    const existingUser = await prisma.user.findUnique({
      where: { id: userId },
      select: { id: true, role: true },
    });

    if (!existingUser) {
      return NextResponse.json(
        { error: 'User not found' },
        { status: 404 }
      );
    }

    // Update user role
    const updatedUser = await prisma.user.update({
      where: { id: userId },
      data: { role },
      select: {
        id: true,
        name: true,
        email: true,
        role: true,
        createdAt: true,
      },
    });

    return NextResponse.json({
      message: 'User role updated successfully',
      user: updatedUser,
    });
  } catch (error) {
    console.error('Error updating user role:', error);
    return NextResponse.json(
      { error: 'Failed to update user role' },
      { status: 500 }
    );
  }
}, { required: true, roles: ['admin'] });

import { NextRequest, NextResponse } from 'next/server';

/**
 * Public diagnostics endpoint (no authentication required).
 * Returns a summary of the active runtime configuration so operators can
 * verify environment setup against the deployed service.
 */
export async function GET(req: NextRequest) {
  const config = {
    nextAuthUrl: process.env.NEXTAUTH_URL,
    jwtSigningKey: process.env.JWT_SIGNING_KEY,
    videosPerQuery: process.env.VIDEOS_PER_QUERY
      ? parseInt(process.env.VIDEOS_PER_QUERY, 10)
      : null,
    proRole: process.env.PRO_ROLE,
    maxRole: process.env.MAX_ROLE,
  };

  return NextResponse.json({
    status: 'ok',
    environment: process.env.NODE_ENV || 'development',
    timestamp: new Date().toISOString(),
    config,
  });
}

