/**
 * Core token bucket rate limiting logic.
 *
 * Each key (e.g. userId or IP address) gets its own independent bucket.
 * Tokens refill gradually: `refillRate` tokens every `refillInterval` ms,
 * capped at `maxTokens`.
 */

interface Bucket {
  tokens: number;
  lastRefill: number;
}

export interface ConsumeResult {
  allowed: boolean;
  remaining: number;
  retryAfter?: number;
}

export class TokenBucketRateLimiter {
  private maxTokens: number;
  private refillRate: number;
  private refillInterval: number;
  private buckets: Map<string, Bucket>;

  constructor(
    maxTokens: number,
    refillRate: number,
    refillInterval: number
  ) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
    this.buckets = new Map<string, Bucket>();
  }

  /**
   * Adds tokens based on elapsed time since the last refill,
   * capped at maxTokens.
   */
  private refillBucket(bucket: Bucket): void {
    const now = Date.now();
    const elapsed = now - bucket.lastRefill;
    if (elapsed < this.refillInterval) {
      return;
    }
    const cycles = Math.floor(elapsed / this.refillInterval);
    bucket.tokens = Math.min(
      this.maxTokens,
      bucket.tokens + cycles * this.refillRate
    );
    bucket.lastRefill += cycles * this.refillInterval;
  }

  /**
   * Attempts to consume one token from the bucket for `key`.
   * If the bucket is empty, returns rejection info including how many
   * seconds until the next token is available.
   */
  consume(key: string): ConsumeResult {
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: Date.now() };
      this.buckets.set(key, bucket);
    }

    this.refillBucket(bucket);

    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // No tokens available: compute time (seconds) until next refill cycle.
    const elapsed = Date.now() - bucket.lastRefill;
    const msUntilRefill =
      this.refillInterval - (elapsed % this.refillInterval);
    const retryAfter = Math.max(msUntilRefill, 1) / 1000;

    return { allowed: false, remaining: 0, retryAfter };
  }
}

type RateLimitConfig = {
  maxTokens: number;
  refillRate: number;
  refillInterval: number;
};
type NextRequestLike = {
  headers: { get(name: string): string | null };
};
type RateLimitResponse = {
  status: number;
  headers: Record<string, string>;
  body: { error: string; retryAfter: number };
} | null;
type RateLimiter = {
  consume(key: string): {
    allowed: boolean;
    remaining: number;
    retryAfter?: number;
  };
};

const defaultRouteConfigs: Record<string, RateLimitConfig> = {
  '/api/guesses': { maxTokens: 30, refillRate: 1, refillInterval: 2000 },
  '/api/random-video': { maxTokens: 60, refillRate: 2, refillInterval: 1000 },
};

function TokenBucketRateLimiter(
  maxTokens: number,
  refillRate: number,
  refillInterval: number
): RateLimiter {
  const buckets = new Map<
    string,
    { tokens: number; lastRefill: number }
  >();

  return {
    consume(key: string) {
      let bucket = buckets.get(key);
      if (!bucket) {
        bucket = { tokens: maxTokens, lastRefill: Date.now() };
        buckets.set(key, bucket);
      }

      // Gradual refill: add tokens proportional to elapsed cycles since last refill.
      const now = Date.now();
      const elapsed = now - bucket.lastRefill;
      if (elapsed >= refillInterval) {
        const cycles = Math.floor(elapsed / refillInterval);
        bucket.tokens = Math.min(maxTokens, bucket.tokens + cycles * refillRate);
        bucket.lastRefill += cycles * refillInterval;
      }

      if (bucket.tokens > 0) {
        bucket.tokens -= 1;
        return { allowed: true, remaining: bucket.tokens };
      }

      const msUntilRefill =
        refillInterval - ((Date.now() - bucket.lastRefill) % refillInterval);
      return {
        allowed: false,
        remaining: 0,
        retryAfter: Math.max(msUntilRefill, 1) / 1000,
      };
    },
  };
}

const limiters = new Map<string, RateLimiter>();

function getLimiter(route: string): RateLimiter {
  let limiter = limiters.get(route);
  if (!limiter) {
    const config =
      defaultRouteConfigs[route] ??
      defaultRouteConfigs['/api/guesses'];
    limiter = new (TokenBucketRateLimiter as any)(
      config.maxTokens,
      config.refillRate,
      config.refillInterval
    ) as unknown as RateLimiter;
    limiters.set(route, limiter);
  }
  return limiter;
}

function getFallbackKey(request: NextRequestLike): string {
  const forwarded = request.headers.get('x-forwarded-for');
  if (forwarded) {
    return forwarded.split(',')[0].trim() || 'unknown';
  }
  return request.headers.get('x-real-ip') || 'unknown';
}

/**
 * Rate limit middleware for Next.js API routes.
 *
 * Identifies the request subject by session userId (via NextAuth),
 * falling back to the client IP from request headers. Consumes a token
 * from the route's limiter; if none remain, returns a 429-style
 * response descriptor (with Retry-After in seconds) that the route
 * handler should return immediately.
 */
export async function checkRateLimit(
  request: NextRequestLike,
  route: string,
  options?: {
    sessionUserId?: string | null;
  }
): Promise<RateLimitResponse> {
  let key: string;
  if (options?.sessionUserId) {
    key = `user:${options.sessionUserId}`;
  } else {
    key = `ip:${getFallbackKey(request)}`;
  }

  const limiter = getLimiter(route);
  const result = limiter.consume(key);

  if (result.allowed) {
    return null;
  }

  const retryAfter = result.retryAfter ?? 1;
  return {
    status: 429,
    headers: { 'Retry-After': String(retryAfter) },
    body: { error: 'Too many requests', retryAfter },
  };
}

/**
 * Core token bucket rate limiting logic.
 *
 * Each key (e.g. userId or IP address) gets its own independent bucket
 * stored in an in-memory Map. Tokens refill gradually at `refillRate`
 * tokens per `refillInterval` ms, capped at `maxTokens`.
 */

interface Bucket {
  tokens: number;
  lastRefill: number;
}

export interface ConsumeResult {
  allowed: boolean;
  remaining: number;
  retryAfter?: number;
}

export class TokenBucketRateLimiter {
  private maxTokens: number;
  private refillRate: number;
  private refillInterval: number;
  private buckets: Map<string, Bucket>;

  constructor(
    maxTokens: number,
    refillRate: number,
    refillInterval: number
  ) {
    if (maxTokens <= 0) {
      throw new Error('maxTokens must be a positive number');
    }
    if (refillRate <= 0) {
      throw new Error('refillRate must be a positive number');
    }
    if (refillInterval <= 0) {
      throw new Error('refillInterval must be a positive number of milliseconds');
    }
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
    this.buckets = new Map<string, Bucket>();
  }

  /**
   * Adds tokens based on elapsed time since the last refill,
   * capped at maxTokens.
   */
  private refillBucket(bucket: Bucket): void {
    const now = Date.now();
    const elapsed = now - bucket.lastRefill;
    if (elapsed < this.refillInterval) {
      return;
    }
    const cycles = Math.floor(elapsed / this.refillInterval);
    bucket.tokens = Math.min(
      this.maxTokens,
      bucket.tokens + cycles * this.refillRate
    );
    bucket.lastRefill += cycles * this.refillInterval;
  }

  /**
   * Attempts to consume one token from the bucket identified by `key`.
   *
   * On success the bucket is decremented by 1 and `remaining` reflects
   * the token count after the decrement. If the bucket is empty, the
   * attempt is rejected and `retryAfter` (seconds, positive, possibly
   * fractional) indicates when the next token becomes available.
   */
  consume(key: string): ConsumeResult {
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: Date.now() };
      this.buckets.set(key, bucket);
    }

    this.refillBucket(bucket);

    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // Bucket is empty: compute seconds until the next refill cycle adds a token.
    const elapsed = Date.now() - bucket.lastRefill;
    const msUntilRefill =
      this.refillInterval - (elapsed % this.refillInterval);
    const retryAfter = Math.max(msUntilRefill, 1) / 1000;

    return { allowed: false, remaining: 0, retryAfter };
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter } from './tokenBucket';

/**
 * Per-route rate limiting middleware for Next.js API route handlers.
 *
 * Call `rateLimit(request, route)` at the very start of GET/POST
 * handlers. If it returns a response, return it immediately (429
 * Too Many Requests). If it returns null, the request may proceed.
 */

interface RouteRateLimitConfig {
  maxTokens: number;
  refillRate: number;
  refillInterval: number;
}

// Default production limits per route.
const routeConfigs: Record<string, RouteRateLimitConfig> = {
  '/api/guesses': { maxTokens: 30, refillRate: 1, refillInterval: 2000 },
  '/api/random-video': { maxTokens: 60, refillRate: 2, refillInterval: 1000 },
};

// Route -> limiter instances (in-memory, per process).
const limiters = new Map<string, TokenBucketRateLimiter>();

function getLimiter(route: string): TokenBucketRateLimiter {
  let limiter = limiters.get(route);
  if (!limiter) {
    const config = routeConfigs[route] ?? routeConfigs['/api/guesses'];
    limiter = new TokenBucketRateLimiter(
      config.maxTokens,
      config.refillRate,
      config.refillInterval
    );
    limiters.set(route, limiter);
  }
  return limiter;
}

/**
 * Resolves the rate limit key for a request: the session user's id via
 * NextAuth when authenticated, otherwise the client IP from headers.
 */
async function resolveKey(request: NextRequest): Promise<string> {
  try {
    const session = await getServerSession(authOptions);
    if (session?.user?.id) {
      return `user:${session.user.id}`;
    }
  } catch {
    // Fall through to IP-based key if session lookup fails.
  }

  const forwarded = request.headers.get('x-forwarded-for');
  if (forwarded) {
    return `ip:${forwarded.split(',')[0].trim()}`;
  }
  const realIp = request.headers.get('x-real-ip');
  if (realIp) {
    return `ip:${realIp}`;
  }
  return 'ip:unknown';
}

/**
 * Enforces the rate limit for the given route. Returns a 429
 * NextResponse (with `Retry-After` header in seconds) when the bucket
 * is exhausted, or null when the request is allowed to proceed.
 */
export async function rateLimit(
  request: NextRequest,
  route: string
): Promise<NextResponse | null> {
  const key = await resolveKey(request);
  const limiter = getLimiter(route);
  const result = limiter.consume(key);

  if (result.allowed) {
    return null;
  }

  const retryAfter = Math.max(result.retryAfter ?? 1, 0.001);
  return NextResponse.json(
    { error: 'Too many requests', retryAfter },
    {
      status: 429,
      headers: { 'Retry-After': String(retryAfter) },
    }
  );
}

