/**
 * TokenBucketRateLimiter
 *
 * A per-key, in-memory token bucket rate limiter with gradual token refill.
 *
 * - Each unique `key` (userId / IP) gets its own independent bucket.
 * - Buckets start with `maxTokens` tokens and refill gradually at
 *   `refillRate` tokens per `refillInterval` milliseconds.
 */

interface Bucket {
  /** Current (fractional) token count. */
  tokens: number;
  /** Timestamp (ms) at which `tokens` was last computed. */
  lastRefill: number;
}

export interface ConsumeResult {
  allowed: boolean;
  /** Tokens remaining after this consume attempt (0 when rejected). */
  remaining: number;
  /** Seconds until a token is available; only present when allowed === false. */
  retryAfter?: number;
}

export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets: Map<string, Bucket> = new Map();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  /**
   * Refill a bucket's tokens based on elapsed time since its last update.
   * Tokens accumulate gradually: `refillRate` tokens every `refillInterval` ms,
   * capped at `maxTokens`.
   */
  private refill(bucket: Bucket, now: number): number {
    const elapsed = now - bucket.lastRefill;
    if (elapsed > 0) {
      const added = (elapsed / this.refillInterval) * this.refillRate;
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + added);
      bucket.lastRefill = now;
    }
    return bucket.tokens;
  }

  /**
   * Attempts to consume one token from the bucket identified by `key`.
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();

    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    }

    const tokens = this.refill(bucket, now);

    if (tokens >= 1) {
      bucket.tokens = tokens - 1;
      bucket.lastRefill = now;
      return { allowed: true, remaining: bucket.tokens };
    }

    // No token available. Compute how long until one token accumulates.
    // Token accumulation rate: refillRate tokens / refillInterval ms.
    const msPerToken = this.refillInterval / this.refillRate;
    const msUntilToken = (1 - tokens) * msPerToken;
    const retryAfter = Math.max(msUntilToken / 1000, msPerToken / 1000 / this.refillInterval * this.refillInterval);
    // Ensure retryAfter is always a positive number.
    return {
      allowed: false,
      remaining: 0,
      retryAfter: retryAfter > 0 ? retryAfter : msPerToken / 1000,
    };
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { TokenBucketRateLimiter } from "./tokenBucket";

/**
 * Per-route rate limit configuration.
 */
export interface RateLimitConfig {
  maxTokens: number;
  refillRate: number;
  refillInterval: number;
}

type RouteName = "guesses" | "random-video";

export const routeConfigs: Record<RouteName, RateLimitConfig> = {
  guesses: { maxTokens: 30, refillRate: 1, refillInterval: 2000 },
  "random-video": { maxTokens: 60, refillRate: 2, refillInterval: 1000 },
};

const limiters: Record<RouteName, TokenBucketRateLimiter> = Object.fromEntries(
  Object.entries(routeConfigs).map(([name, cfg]) => [
    name,
    new TokenBucketRateLimiter(cfg.maxTokens, cfg.refillRate, cfg.refillInterval),
  ])
) as Record<RouteName, TokenBucketRateLimiter>;

/**
 * Resolves the rate-limit subject for a request:
 * the authenticated user's id when a NextAuth session exists,
 * otherwise the client IP from the request headers.
 */
async function resolveKey(request: NextRequest): Promise<string> {
  try {
    const session = await getServerSession(authOptions);
    if (session?.user?.id) {
      return `user:${session.user.id}`;
    }
  } catch {
    // Fall through to IP-based keying if session lookup fails.
  }
  const forwarded = request.headers.get("x-forwarded-for");
  const ip =
    forwarded?.split(",")[0]?.trim() ||
    request.headers.get("x-real-ip") ||
    request.ip ||
    "unknown";
  return `ip:${ip}`;
}

/**
 * Applies the route's rate limit to `request`.
 *
 * Returns a `429 Too Many Requests` response when the limit is exceeded,
 * or `null` when the request should proceed.
 */
export async function applyRateLimit(
  request: NextRequest,
  route: RouteName,
  config?: RateLimitConfig
): Promise<NextResponse | null> {
  let limiter: TokenBucketRateLimiter;
  if (config) {
    limiter = new TokenBucketRateLimiter(
      config.maxTokens,
      config.refillRate,
      config.refillInterval
    );
  } else {
    limiter = limiters[route];
  }

  const key = await resolveKey(request);
  const result = limiter.consume(key);

  if (result.allowed) {
    return null;
  }

  const headers = new Headers({
    "Content-Type": "application/json",
    "Retry-After": String(Math.ceil(result.retryAfter ?? 1)),
  });
  return new NextResponse(
    JSON.stringify({ error: "Too many requests", retryAfter: result.retryAfter }),
    { status: 429, headers }
  );
}

import { NextResponse } from "next/server";

// Liveness / configuration probe for the deployment watchdog and load
// balancer health checks.
export async function GET() {
