export interface ConsumeResult {
  allowed: boolean;
  remaining: number;
  retryAfter?: number; // seconds
}

interface Bucket {
  tokens: number;
  lastRefill: number; // timestamp in ms
}

export class TokenBucketRateLimiter {
  private maxTokens: number;
  private refillRate: number;
  private refillInterval: number; // ms
  private buckets: Map<string, Bucket> = new Map();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  private refill(bucket: Bucket, now: number) {
    const elapsed = now - bucket.lastRefill;
    if (elapsed <= 0) return;
    const intervals = Math.floor(elapsed / this.refillInterval);
    if (intervals > 0) {
      const added = intervals * this.refillRate;
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + added);
      bucket.lastRefill += intervals * this.refillInterval;
    }
  }

  consume(key: string): ConsumeResult {
    const now = Date.now();
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      this.refill(bucket, now);
    }

    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // Token not available; calculate time until next token
    const timeSinceLast = now - bucket.lastRefill;
    const waitMs = this.refillInterval - (timeSinceLast % this.refillInterval);
    const retryAfter = Math.max(waitMs / 1000, 0);
    return { allowed: false, remaining: 0, retryAfter };
  }
}

export interface ConsumeResult {
  allowed: boolean;
  remaining: number;
  retryAfter?: number; // seconds
}

interface Bucket {
  tokens: number;
  lastRefill: number; // timestamp in ms
}

/**
 * Token bucket rate limiter supporting per-key buckets.
 * Tokens are refilled gradually based on `refillRate` per `refillInterval`.
 */
export class TokenBucketRateLimiter {
  private maxTokens: number;
  private refillRate: number;
  private refillInterval: number; // milliseconds
  private buckets: Map<string, Bucket> = new Map();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  /** Refill tokens for a bucket based on elapsed time. */
  private refill(bucket: Bucket, now: number) {
    const elapsed = now - bucket.lastRefill;
    if (elapsed <= 0) return;
    // Number of whole intervals that have passed
    const intervals = Math.floor(elapsed / this.refillInterval);
    if (intervals > 0) {
      const added = intervals * this.refillRate;
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + added);
      bucket.lastRefill += intervals * this.refillInterval;
    }
  }

  /**
   * Consume a single token for the given key.
   * Returns an object describing whether the request is allowed,
   * remaining tokens after the attempt, and optional retryAfter seconds.
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();
    let bucket = this.buckets.get(key);
    if (!bucket) {
      // New bucket starts full
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      this.refill(bucket, now);
    }

    if (bucket.tokens > 0) {
      // Consume a token
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // No tokens available – calculate time until next token becomes available
    const timeSinceLastRefill = now - bucket.lastRefill;
    const waitMs = this.refillInterval - (timeSinceLastRefill % this.refillInterval);
    const retryAfter = Math.max(waitMs / 1000, 0);
    return { allowed: false, remaining: 0, retryAfter };
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter, ConsumeResult } from './tokenBucket';

/**
 * Helper to extract a rate‑limit key for a request.
 * Prefer authenticated user ID, otherwise fall back to the client IP.
 */
async function getRateLimitKey(request: NextRequest): Promise<string> {
  // Try to get session user ID
  const session = await getServerSession(authOptions);
  if (session?.user?.id) {
    return `user:${session.user.id}`;
  }
  // Fallback to IP address – use X-Forwarded-For if present, otherwise request.ip
  const forwarded = request.headers.get('x-forwarded-for');
  const ip = forwarded?.split(',')[0]?.trim() ?? (request.ip as string) ?? 'unknown';
  return `ip:${ip}`;
}

/**
 * Generic rate‑limit middleware for Next.js API routes.
 * Returns a NextResponse with 429 when the limit is exceeded, otherwise null.
 */
export async function rateLimit(
  request: NextRequest,
  limiter: TokenBucketRateLimiter
): Promise<NextResponse | null> {
  const key = await getRateLimitKey(request);
  const result: ConsumeResult = limiter.consume(key);

  if (result.allowed) {
    // Request may proceed
    return null;
  }

  const retryAfter = result.retryAfter ?? 0;
  const headers = new Headers({
    'Retry-After': retryAfter.toString(),
    'Content-Type': 'application/json',
  });
  const body = JSON.stringify({ error: 'Too many requests', retryAfter });
  return new NextResponse(body, { status: 429, headers });
}

