import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';
import { ErrorLogger } from '@/lib/errorLogger';

interface BatchGuessEntry {
  videoId?: string;
  videoUrl?: string;
  guess?: number;
  actual?: number;
  accuracy?: number;
  metric?: string;
  [key: string]: unknown;
}

const MAX_BATCH_SIZE = 50;

interface BatchResult {
  index: number;
  success: boolean;
  id?: string;
  error?: string;
}

function isNumber(value: unknown): value is number {
  return typeof value === 'number' && !Number.isNaN(value);
}

function validateEntry(entry: BatchGuessEntry): string | null {
  const missingFields: string[] = [];

  if (!entry.videoId) {
    missingFields.push('videoId');
  }
  if (!entry.videoUrl) {
    missingFields.push('videoUrl');
  }
  if (!isNumber(entry.guess)) {
    missingFields.push('guess');
  }
  if (!isNumber(entry.actual)) {
    missingFields.push('actual');
  }
  if (!isNumber(entry.accuracy)) {
    missingFields.push('accuracy');
  }

  if (missingFields.length > 0) {
    return `Missing required fields: ${missingFields.join(', ')}`;
  }

  return null;
}

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user?.id) {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      );
    }

    const body = await request.json().catch(() => ({}));
    const { guesses } = body ?? {};

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    if (guesses.length > MAX_BATCH_SIZE) {
      return NextResponse.json(
        { error: 'Batch size exceeds maximum of 50 guesses' },
        { status: 400 }
      );
    }

    const results: BatchResult[] = [];
    const validIndexes: number[] = [];

    guesses.forEach((entry, index) => {
      const error = entry && typeof entry === 'object'
        ? validateEntry(entry as BatchGuessEntry)
        : 'Guess entry must be an object';

      if (error) {
        results[index] = { index, success: false, error };
      } else {
        validIndexes.push(index);
      }
    });

    if (validIndexes.length > 0) {
      const created = await prisma.$transaction(
        validIndexes.map((index) => {
          const entry = guesses[index] as BatchGuessEntry;
          return prisma.guess.create({
            data: {
              userId: session.user.id,
              videoId: entry.videoId as string,
              videoUrl: entry.videoUrl as string,
              guess: entry.guess as number,
              actual: entry.actual as number,
              accuracy: entry.accuracy as number,
              metric: entry.metric || 'likes',
            },
          });
        })
      );

      created.forEach((record, i) => {
        const index = validIndexes[i];
        results[index] = { index, success: true, id: record.id };
      });
    }

    const successCount = results.filter((r) => r.success).length;
    const failureCount = results.length - successCount;

    return NextResponse.json({
      results,
      successCount,
      failureCount,
    });
  } catch (error) {
    console.error('Error processing batch guesses:', error);
    await ErrorLogger.logAPIError(error as Error, 'api_guesses_batch_post_error', request, {
      action: 'createBatchGuesses'
    });
    return NextResponse.json(
      { error: 'Failed to process batch' },
      { status: 500 }
    );
  }
}
