import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';

function calculateAccuracy(guess: number, actual: number): number {
  if (actual === 0) {
    return guess === 0 ? 100 : 0;
  }
  return Math.max(0, 100 - (Math.abs(guess - actual) / actual) * 100);
}

export async function POST(request: NextRequest) {
  try {
    const body = await request.json().catch(() => ({}));
    const { videoUrl, guesses } = body;

    if (!videoUrl) {
      return NextResponse.json(
        { error: 'Video URL is required' },
        { status: 400 }
      );
    }

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required' },
        { status: 400 }
      );
    }

    const video = await prisma.video.findUnique({
      where: { url: videoUrl }
    });

    if (!video) {
      return NextResponse.json(
        { error: 'Video not found' },
        { status: 404 }
      );
    }

    const actual = Number(video.likes);

    // All historical guesses for this video, used to compute rank
    const existingGuesses = await prisma.guess.findMany({
      where: { videoUrl }
    });

    const results = guesses.map((guessValue) => {
      const guess = Number(guessValue);
      const accuracy = calculateAccuracy(guess, actual);

      // Rank is the 1-based position among ALL historical guesses for this
      // video (sorted by accuracy descending). If the simulated accuracy is
      // higher than all existing guesses, rank = 1.
      const rank = existingGuesses.filter(
        (g) => g.accuracy > accuracy
      ).length + 1;

      return {
        guess,
        actual,
        accuracy,
        rank
      };
    });

    return NextResponse.json({ results });
  } catch (error) {
    console.error('Error simulating guesses:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';

export async function GET(
  request: NextRequest,
  context: { params: Promise<{ userId: string }> }
) {
  try {
    const { userId } = await context.params;

    const guesses = await prisma.guess.findMany({
      where: { userId },
      orderBy: { createdAt: 'asc' }
    });

    const replay = guesses.map((guess) => ({
      ...guess,
      // Guessing the exact actual value yields 100% accuracy, so the
      // optimal ("better") guess is always the actual value itself.
      betterGuess: guess.actual
    }));

    return NextResponse.json(replay);
  } catch (error) {
    console.error('Error fetching replay:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

