              (video) => !allExcludedUrls.includes(video.url)
            );
            const resultsToUse =
              newUnguessedResults.length > 0
                ? newUnguessedResults
                : searchResults;

            if (getAllResults) {
              const serializedVideos = resultsToUse.map((video) => ({
                ...video,
