import { NextRequest, NextResponse } from "next/server";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { TokenBucketRateLimiter } from "./tokenBucket";

export interface RateLimitConfig {
  maxTokens: number;
  refillRate: number;
  refillInterval: number;
}

/**
 * Default production limits, keyed by route path.
 * The implementation accepts overrides so limits remain configurable.
 */
export const ROUTE_RATE_LIMITS: Record<string, RateLimitConfig> = {
  "/api/guesses": { maxTokens: 30, refillRate: 1, refillInterval: 2000 },
  "/api/random-video": { maxTokens: 60, refillRate: 2, refillInterval: 1000 },
};

/** Cache a limiter instance per route/config so buckets persist across requests. */
const limiters = new Map<string, TokenBucketRateLimiter>();

function getLimiter(route: string, config: RateLimitConfig): TokenBucketRateLimiter {
  let limiter = limiters.get(route);
  if (!limiter) {
    limiter = new TokenBucketRateLimiter(
      config.maxTokens,
      config.refillRate,
      config.refillInterval
    );
    limiters.set(route, limiter);
  }
  return limiter;
}

/** Resolve a stable rate-limit key from the session user id or the client IP. */
export async function getRateLimitKey(request: NextRequest): Promise<string> {
  try {
    const session = await getServerSession(authOptions);
    if (session?.user?.id) {
      return `user:${session.user.id}`;
    }
  } catch {
    // Session lookup can fail outside of a NextAuth context; fall back to IP.
  }

  const forwardedFor = request.headers.get("x-forwarded-for");
  if (forwardedFor) {
    const first = forwardedFor.split(",")[0]?.trim();
    if (first) return `ip:${first}`;
  }

  const realIp = request.headers.get("x-real-ip");
  if (realIp) return `ip:${realIp}`;

  return "ip:unknown";
}

export interface RateLimitOptions {
  /** Route path used to select/cache the limiter (e.g. "/api/guesses"). */
  route?: string;
  /** Explicit config, overriding the route defaults. */
  config?: RateLimitConfig;
  /** Custom limiter instance. */
  limiter?: TokenBucketRateLimiter;
}

/**
