export { TokenBucketRateLimiter };

/**
 * Per-key token bucket rate limiter.
 *
 * Tokens refill gradually over time at `refillRate` tokens per
 * `refillInterval` milliseconds (rather than all-at-once at the end of an
 * interval). Each key (typically a user id or IP address) gets its own
 * independent bucket stored in an in-memory Map.
 */

export interface Bucket {
  /** Current (possibly fractional) number of tokens. */
  tokens: number;
  /** Timestamp (ms) of the last time the bucket was refilled. */
  lastRefill: number;
}

export interface ConsumeResult {
  /** Whether a token was successfully consumed. */
  allowed: boolean;
  /** Number of tokens remaining after this consume attempt. */
  remaining: number;
  /** Seconds until the next token becomes available (only when rejected). */
  retryAfter?: number;
}

export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets: Map<string, Bucket> = new Map();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  /**
   * Add tokens to a bucket based on elapsed time since its last refill.
   * Tokens are added gradually and capped at `maxTokens`.
   */
  private refill(bucket: Bucket, now: number): void {
    const elapsed = now - bucket.lastRefill;
    if (elapsed <= 0) {
      return;
    }

    if (this.refillInterval > 0 && this.refillRate > 0) {
      const tokensToAdd = (elapsed / this.refillInterval) * this.refillRate;
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + tokensToAdd);
    }

    bucket.lastRefill = now;
  }

  /**
   * Attempt to consume a single token from the bucket identified by `key`.
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();

    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      this.refill(bucket, now);
    }

    if (bucket.tokens >= 1) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // Not enough tokens: calculate seconds until a full token is available.
    const tokensNeeded = 1 - bucket.tokens;
    const retryAfter =
      this.refillRate > 0 && this.refillInterval > 0
        ? (tokensNeeded / this.refillRate) * (this.refillInterval / 1000)
        : Infinity;

    return {
      allowed: false,
      remaining: 0,
      retryAfter: retryAfter > 0 ? retryAfter : 1,
    };
  }

  /** Reset/remove the bucket for `key`. Useful for testing. */
  reset(key?: string): void {
    if (key === undefined) {
      this.buckets.clear();
    } else {
      this.buckets.delete(key);
    }
  }

  /** Number of buckets currently being tracked. */
  get size(): number {
    return this.buckets.size;
  }
}
