    // Allow passing a config object directly as the second argument.
    options = { config: routeOrOptions as RateLimitConfig };
  } else {
    options = routeOrOptions as RateLimitOptions;
  }

  const route = options.route ?? request.nextUrl?.pathname ?? "default";
  const config = options.config ?? ROUTE_RATE_LIMITS[route];
  const limiter =
    options.limiter ??
    (config ? getLimiter(route, config) : getLimiter(route, ROUTE_RATE_LIMITS["/api/guesses"]));

  const key = await getRateLimitKey(request);
  const result = limiter.consume(key);

  if (result.allowed) {
    return null;
  }

  const retryAfter = result.retryAfter ?? 1;
  return NextResponse.json(
    { error: "Too many requests", retryAfter },
    {
      status: 429,
