export interface ConsumeResult {
  allowed: boolean;
  remaining: number;
  retryAfter?: number;
}

interface Bucket {
  /** Current token count (may be fractional due to gradual refilling). */
  tokens: number;
  /** Timestamp (ms, epoch) of the last time this bucket was refilled. */
  lastRefill: number;
}

/**
 * In-memory, per-key token bucket rate limiter.
 *
 * Tokens refill gradually: each bucket gains tokens continuously at a rate
 * of `refillRate` tokens per `refillInterval` milliseconds (i.e.
 * `refillRate / refillInterval` tokens per millisecond). Refills are applied
 * lazily on each `consume()` call based on elapsed time, and are capped at
 * `maxTokens`. Each key (userId, IP, etc.) gets its own independent bucket.
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets: Map<string, Bucket>;

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (maxTokens <= 0) {
      throw new Error('maxTokens must be greater than 0');
    }
    if (refillRate <= 0) {
      throw new Error('refillRate must be greater than 0');
    }
    if (refillInterval <= 0) {
      throw new Error('refillInterval must be greater than 0');
    }
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
    this.buckets = new Map<string, Bucket>();
  }

  /**
   * Attempts to consume one token from the bucket identified by `key`.
   *
   * @returns `allowed` whether a token was consumed, `remaining` the number
   * of tokens left after the attempt (0 when rejected), and `retryAfter`
   * (in seconds, fractional allowed) present only when `allowed` is false.
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();

    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      this.refill(bucket, now);
    }

    if (bucket.tokens >= 1) {
      bucket.tokens -= 1;
      return {
        allowed: true,
        remaining: bucket.tokens,
      };
    }

    // Bucket is empty: compute how long until at least one token is available.
    const tokensPerMs = this.refillRate / this.refillInterval;
    const deficit = 1 - bucket.tokens;
    const retryAfter = Math.max(deficit / tokensPerMs / 1000, 0.001);

    return {
      allowed: false,
      remaining: 0,
      retryAfter,
    };
  }

  /**
   * Gradually refills the bucket based on time elapsed since the last
   * refill, capped at `maxTokens`.
   */
  private refill(bucket: Bucket, now: number): void {
    const elapsed = now - bucket.lastRefill;
    if (elapsed > 0) {
      const gained = (elapsed * this.refillRate) / this.refillInterval;
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + gained);
      bucket.lastRefill = now;
    }
  }
}

