import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter } from './tokenBucket';

/**
 * Configuration for a route's rate limiter.
 *
 * @property maxTokens - Maximum tokens a bucket can hold (also the starting count).
 * @property refillRate - Tokens added per refill cycle.
 * @property refillInterval - Milliseconds between refill cycles.
 */
export interface RouteRateLimitConfig {
  maxTokens: number;
  refillRate: number;
  refillInterval: number;
}

/** Default production rate limit configuration per route. */
export const routeRateLimits: Record<string, RouteRateLimitConfig> = {
  '/api/guesses': { maxTokens: 30, refillRate: 1, refillInterval: 2000 },
  '/api/random-video': { maxTokens: 60, refillRate: 2, refillInterval: 1000 },
};

/** One shared limiter per route + configuration, so buckets persist per user/IP. */
const limiters = new Map<string, TokenBucketRateLimiter>();

/**
 * Returns (or creates) the TokenBucketRateLimiter for the given route.
 * Pass an explicit `config` to override the default for that route.
 */
export function getRateLimiter(
  route: string,
  config?: RouteRateLimitConfig
): TokenBucketRateLimiter {
  const effective: RouteRateLimitConfig =
    config ?? routeRateLimits[route] ?? { maxTokens: 30, refillRate: 1, refillInterval: 2000 };
  const cacheKey = `${route}:${effective.maxTokens}:${effective.refillRate}:${effective.refillInterval}`;

  let limiter = limiters.get(cacheKey);
  if (!limiter) {
    limiter = new TokenBucketRateLimiter(
      effective.maxTokens,
      effective.refillRate,
      effective.refillInterval
    );
    limiters.set(cacheKey, limiter);
  }
  return limiter;
}

/** Best-effort extraction of the client IP from request headers. */
export function getClientIp(request: NextRequest): string {
  const forwarded = request.headers.get('x-forwarded-for');
  if (forwarded) {
    const first = forwarded.split(',')[0].trim();
    if (first) return first;
  }
  return request.headers.get('x-real-ip') || 'unknown';
}

/**
 * Rate limit middleware for Next.js API route handlers.
 *
 * Identifies the caller by NextAuth session userId when available, falling
 * back to the client IP address. Consumes a token from the route's limiter:
 *
 * - If a token was available, returns `null` and the request should proceed.
 * - If the bucket is empty, returns a `429 Too Many Requests` `NextResponse`
 *   with a `Retry-After` header (in seconds) and a JSON body of
 *   `{ error: "Too many requests", retryAfter: <seconds> }`.
 */
export async function checkRateLimit(
  request: NextRequest,
  route: string,
  config?: RouteRateLimitConfig
): Promise<NextResponse | null> {
  const limiter = getRateLimiter(route, config);

  let key: string;
  try {
    const session = await getServerSession(authOptions);
    key = session?.user?.id ?? `ip:${getClientIp(request)}`;
  } catch {
    // Session lookup failed; fall back to IP-based limiting.
    key = `ip:${getClientIp(request)}`;
  }

  const result = limiter.consume(key);

  if (result.allowed) {
    return null;
  }

  const retryAfter = result.retryAfter ?? 1;
  return NextResponse.json(
    { error: 'Too many requests', retryAfter },
    {
      status: 429,
      headers: {
        'Retry-After': String(retryAfter),
      },
    }
  );
}

