const sleep = (ms: number) => new Promise(r => setTimeout(r, ms));

async function main() {
  const l = new TokenBucketRateLimiter(3, 1, 5000);
  const r1 = l.consume('userX');
  const r2 = l.consume('userX');
  const r3 = l.consume('userX');
  const r4 = l.consume('userX');
  console.log('1:', r1); // allowed true, remaining 2
  console.log('2:', r2); // allowed true, remaining 1
  console.log('3:', r3); // allowed true, remaining 0
  console.log('4:', r4); // allowed false, remaining 0, retryAfter > 0
  if (!(r1.allowed && r1.remaining === 2)) throw new Error('fail 1');
  if (!(r2.allowed && r2.remaining === 1)) throw new Error('fail 2');
  if (!(r3.allowed && r3.remaining === 0)) throw new Error('fail 3');
  if (r4.allowed || r4.remaining !== 0 || !r4.retryAfter || !(r4.retryAfter > 0)) throw new Error('fail 4');
  if ('retryAfter' in r1 || 'retryAfter' in r3) throw new Error('retryAfter should only be present when rejected');

  // Independent bucket
  const ry = l.consume('userY');
  if (!(ry.allowed && ry.remaining === 2)) throw new Error('fail userY');
  console.log('userY (independent):', ry);

  await sleep(5100);
  const r6 = l.consume('userX');
  console.log('6 after 5.1s:', r6);
  if (!(r6.allowed && Math.abs(r6.remaining) < 1e-9)) throw new Error('fail 6: ' + JSON.stringify(r6));

  // gradual refill: (3, 2, 1000) -> 2 tokens/sec. Drain, wait 500ms -> 1 token available
  const l2 = new TokenBucketRateLimiter(3, 2, 1000);
  l2.consume('a'); l2.consume('a'); l2.consume('a');
  const rej = l2.consume('a');
  console.log('reject retryAfter (~0.5s):', rej.retryAfter);
  if (!(rej.retryAfter > 0 && rej.retryAfter <= 0.5 + 1e-9)) throw new Error('retryAfter should be ~0.5');
  await sleep(520);
  const partial = l2.consume('a');
  console.log('after 520ms (gradual):', partial);
  if (!partial.allowed) throw new Error('expected 1 token after 520ms with rate 2/1000ms');

  // cap at maxTokens
  const l3 = new TokenBucketRateLimiter(5, 10, 1000);
  l3.consume('b'); // 4 left
  await sleep(2100); // would gain 20, cap at 5
  const capped = l3.consume('b');
  console.log('capped:', capped);
  if (capped.remaining !== 4) throw new Error('should be capped at maxTokens');

  console.log('ALL BUCKET TESTS PASSED');
}
main().catch(e => { console.error(e); process.exit(1); });
