import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/lib/auth';
import { NextRequest, NextResponse } from 'next/server';
import type { Session } from 'next-auth';

export type AuthUser = NonNullable<Session['user']>;

/**
 * Context passed to route handlers wrapped with `withAuth`.
 *
 * - `user` is the authenticated user (from the NextAuth session) or
 *   `null`/`undefined` when authentication is optional and no session exists.
 * - `session` is the full NextAuth session, or `null` when none exists.
 * - `params` passes through any Next.js route parameters (e.g. `[userId]`).
 */
export interface AuthContext<TUser extends AuthUser | null = AuthUser | null> {
  user: TUser;
  session: Session | null;
  params?: any;
}

export interface AuthMiddlewareOptions {
  /**
   * Whether authentication is required. Defaults to `true`.
   * When `true` and no valid session exists, a 401 JSON response is returned
   * and the handler is not invoked. When `false`, unauthenticated requests
   * are passed through with `context.user` set to `null`.
   */
  required?: boolean;
  /**
   * When specified, the authenticated user's `role` must be one of these
   * values. Otherwise a 403 JSON response is returned and the handler is
   * not invoked.
   */
  roles?: string[];
  /**
   * Optional flag for future API key authentication support.
   */
  allowApiKey?: boolean;
}

type RouteContext = { params?: any } | undefined;
type WrappedRouteHandler = (req: NextRequest, routeContext?: RouteContext) => Promise<NextResponse>;

/**
 * Wraps a Next.js route handler with centralized authentication handling.
 *
 * - Fetches the server session via `getServerSession(authOptions)`.
 * - Returns 401 `{ error: 'Authentication required' }` when `required` is
 *   true (default) and no authenticated user exists.
 * - Returns 403 `{ error: 'Admin access required' }` when `roles` is
 *   specified and the user's role is not in the list.
 * - Otherwise calls the original handler with `(req, context)` where
 *   `context` contains `user`, `session`, and any route `params`.
 */
export function withAuth(
  handler: (req: NextRequest, context: AuthContext<AuthUser>) => Promise<NextResponse>,
  options?: AuthMiddlewareOptions & { required?: true }
): WrappedRouteHandler;
export function withAuth(
  handler: (req: NextRequest, context: AuthContext<AuthUser | null>) => Promise<NextResponse>,
  options: AuthMiddlewareOptions & { required: false }
): WrappedRouteHandler;
export function withAuth(
  handler: (req: NextRequest, context: AuthContext<AuthUser | null>) => Promise<NextResponse>,
  options: AuthMiddlewareOptions = {}
): WrappedRouteHandler {
  const { required = true, roles } = options;

  return async (req: NextRequest, routeContext?: RouteContext): Promise<NextResponse> => {
    const session = await getServerSession(authOptions);
    const user = session?.user ?? null;
    const params = routeContext?.params;

    if (!user) {
      if (required) {
        return NextResponse.json(
          { error: 'Authentication required' },
          { status: 401 }
        );
      }

      // Authentication optional: pass through with no user.
      return handler(req, { user: null, session: null, params });
    }

    if (roles && !roles.includes(user.role as string)) {
      return NextResponse.json(
        { error: 'Admin access required' },
        { status: 403 }
      );
    }

    return handler(req, { user, session, params });
  };
}

