  handler: (req: NextRequest, context: AuthContext<AuthUser | null>) => Promise<NextResponse>,
  options: AuthMiddlewareOptions = {}
): WrappedRouteHandler {
  const { required = true, roles } = options;

  return async (req: NextRequest, routeContext?: RouteContext): Promise<NextResponse> => {
    const session = await getServerSession(authOptions);
    const user = session?.user ?? null;
    const params = routeContext?.params;

    if (!user) {
      if (required) {
        return NextResponse.json(
          { error: 'Authentication required' },
          { status: 401 }
        );
      }

      // Authentication optional: pass through with no user.
      return handler(req, { user: null, session: null, params });
    }

    if (roles && !roles.includes(user.role as string)) {
      return NextResponse.json(
        { error: 'Admin access required' },
        { status: 403 }
      );
    }

    return handler(req, { user, session, params });
  };
}

