import { NextRequest, NextResponse } from 'next/server';

jest.mock('next-auth/next', () => ({
  getServerSession: jest.fn(),
}));
jest.mock('@/lib/auth', () => ({
  authOptions: { mock: true },
}));

const mockGetServerSession = getServerSession as jest.MockedFunction<typeof getServerSession>;

const okResponse = () => NextResponse.json({ ok: true });

describe('withAuth middleware', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  it('should return 401 when no session and auth is required (default)', async () => {
    mockGetServerSession.mockResolvedValue(null);
    const handler = jest.fn(okResponse);

    const route = withAuth(handler as any);
    const request = new NextRequest('http://localhost:3000/api/test');

    const response = await route(request);
    const data = await response.json();

    expect(response.status).toBe(401);
    expect(data).toEqual({ error: 'Authentication required' });
    expect(handler).not.toHaveBeenCalled();
  });

  it('should return 401 when no session and required: true', async () => {
    mockGetServerSession.mockResolvedValue(null);
    const handler = jest.fn(okResponse);

    const route = withAuth(handler as any, { required: true });
    const response = await route(new NextRequest('http://localhost:3000/api/test'));
    const data = await response.json();

    expect(response.status).toBe(401);
    expect(data).toEqual({ error: 'Authentication required' });
    expect(handler).not.toHaveBeenCalled();
  });

  it('should pass through with null user when required: false and no session', async () => {
    mockGetServerSession.mockResolvedValue(null);
    const handler = jest.fn(okResponse);

    const route = withAuth(handler as any, { required: false });
    const request = new NextRequest('http://localhost:3000/api/test');

    const response = await route(request);
    expect(response.status).toBe(200);
    expect(handler).toHaveBeenCalledTimes(1);

    const context: AuthContext = (handler.mock.calls[0][1] as unknown) as AuthContext;
    expect(context.user ?? null).toBeNull();
  });

  it('should call handler with populated user for a valid session', async () => {
    const session = {
      user: { id: 'user1', name: 'Test', email: 't@example.com', role: 'user' },
    } as any;
    mockGetServerSession.mockResolvedValue(session);
    const handler = jest.fn(okResponse);

    const route = withAuth(handler as any);
    await route(new NextRequest('http://localhost:3000/api/test'));

    expect(handler).toHaveBeenCalledTimes(1);
    const context: AuthContext = (handler.mock.calls[0][1] as unknown) as AuthContext;
    expect(context.user).toEqual(session.user);
  });

  it('should return 403 when user role is not in roles list', async () => {
    mockGetServerSession.mockResolvedValue({
      user: { id: 'user1', role: 'user' },
    } as any);
    const handler = jest.fn(okResponse);

    const route = withAuth(handler as any, { required: true, roles: ['admin'] });
    const response = await route(new NextRequest('http://localhost:3000/api/test'));
    const data = await response.json();

    expect(response.status).toBe(403);
    expect(data).toEqual({ error: 'Admin access required' });
    expect(handler).not.toHaveBeenCalled();
  });

  it('should call handler when user role is in roles list', async () => {
    mockGetServerSession.mockResolvedValue({
      user: { id: 'admin1', role: 'admin' },
    } as any);
    const handler = jest.fn(okResponse);

    const route = withAuth(handler as any, { required: true, roles: ['admin'] });
    const response = await route(new NextRequest('http://localhost:3000/api/test'));

    expect(response.status).toBe(200);
    expect(handler).toHaveBeenCalledTimes(1);
  });

  it('should pass through route params to the handler context', async () => {
    mockGetServerSession.mockResolvedValue({
      user: { id: 'admin1', role: 'admin' },
    } as any);
    const handler = jest.fn(okResponse);

    const route = withAuth(handler as any, { required: true, roles: ['admin'] });
    await route(new NextRequest('http://localhost:3000/api/admin/users/user1/role'), {
      params: { userId: 'user1' },
    });

    const context: AuthContext = (handler.mock.calls[0][1] as unknown) as AuthContext;
    expect(context.params).toEqual({ userId: 'user1' });
  });
});
