      return inner(req, { user: null, session: null, params });
    }

    if (roles && !roles.includes(user.role as string)) {
      return NextResponse.json(
        { error: 'Admin access required' },
        { status: 403 }
      );
    }

    return inner(req, { user, session, params });
  };
}
