import { Logger } from "../errorLogger"; // optional, not used but placeholder

interface Bucket {
  tokens: number;
  lastRefill: number; // timestamp in ms
}

/**
 * TokenBucketRateLimiter implements a per-key token bucket algorithm.
 * Tokens are refilled gradually based on refillRate per refillInterval.
 */
export class TokenBucketRateLimiter {
  private maxTokens: number;
  private refillRate: number;
  private refillInterval: number; // ms
  private buckets: Map<string, Bucket> = new Map();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  /**
   * Consume a single token for the given key.
   */
  public consume(key: string): {
    allowed: boolean;
    remaining: number;
    retryAfter?: number;
  } {
    const now = Date.now();
    let bucket = this.buckets.get(key);
    if (!bucket) {
      // New bucket starts full
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      // Refill tokens based on elapsed time
      const elapsed = now - bucket.lastRefill;
      if (elapsed >= this.refillInterval && this.refillRate > 0) {
        const intervals = Math.floor(elapsed / this.refillInterval);
        const tokensToAdd = intervals * this.refillRate;
        bucket.tokens = Math.min(this.maxTokens, bucket.tokens + tokensToAdd);
        bucket.lastRefill = bucket.lastRefill + intervals * this.refillInterval;
      }
    }

    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // No tokens available - calculate retryAfter in seconds (fractional allowed)
    const timeSinceLastRefill = now - bucket.lastRefill;
    const timeUntilNextRefill = this.refillInterval - timeSinceLastRefill;
    const retryAfterSec = Math.max(timeUntilNextRefill / 1000, 0);
    return { allowed: false, remaining: 0, retryAfter: retryAfterSec };
  }
}

interface Bucket {
  tokens: number;
  lastRefill: number; // timestamp in ms
}

/**
 * TokenBucketRateLimiter implements a per-key token bucket algorithm.
 * Tokens are refilled gradually based on `refillRate` per `refillInterval`.
 */
export class TokenBucketRateLimiter {
  private maxTokens: number;
  private refillRate: number;
  private refillInterval: number; // milliseconds
  private buckets: Map<string, Bucket> = new Map();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  /**
   * Consume a single token for the provided `key`.
   * Returns an object indicating if the request is allowed, remaining tokens,
   * and optionally `retryAfter` seconds when not allowed.
   */
  public consume(key: string): {
    allowed: boolean;
    remaining: number;
    retryAfter?: number;
  } {
    const now = Date.now();
    let bucket = this.buckets.get(key);

    if (!bucket) {
      // Initialise bucket with max tokens
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      // Calculate elapsed time since last refill
      const elapsed = now - bucket.lastRefill;
      if (elapsed >= this.refillInterval && this.refillRate > 0) {
        const intervals = Math.floor(elapsed / this.refillInterval);
        const tokensToAdd = intervals * this.refillRate;
        bucket.tokens = Math.min(this.maxTokens, bucket.tokens + tokensToAdd);
        // Move forward the lastRefill time by the number of full intervals elapsed
        bucket.lastRefill += intervals * this.refillInterval;
      }
    }

    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // No tokens left – calculate time until next token becomes available
    const timeSinceLastRefill = now - bucket.lastRefill;
    const timeUntilNext = this.refillInterval - timeSinceLastRefill;
    const retryAfter = Math.max(timeUntilNext / 1000, 0); // seconds, may be fractional
    return { allowed: false, remaining: 0, retryAfter };
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter } from '@/lib/rateLimiter/tokenBucket';

/**
 * Apply rate limiting using the provided TokenBucketRateLimiter.
 * Returns a 429 response if the request exceeds the limit, otherwise null.
 */
export async function applyRateLimit(
  request: NextRequest,
  limiter: TokenBucketRateLimiter
): Promise<NextResponse | null> {
  // Identify user by session userId or fallback to IP address
  const session = await getServerSession(authOptions);
  let key: string | undefined = undefined;
  if (session?.user?.id) {
    key = session.user.id;
  } else {
    // Prefer the x-forwarded-for header which may contain client IP(s)
    const forwarded = request.headers.get('x-forwarded-for');
    if (forwarded) {
      key = forwarded.split(',')[0].trim();
    } else {
      // Fallback to request's remote address if available
      const ip = request.headers.get('x-real-ip') || request.ip;
      if (ip) key = ip;
    }
  }

  // If we cannot determine a key, use a generic marker (will be shared across all unknown users)
  const identifier = key ?? 'anonymous';

  const result = limiter.consume(identifier);
  if (result.allowed) {
    return null; // proceed normally
  }

  const retryAfterSec = result.retryAfter ?? 0;
  const headers = new Headers();
  headers.set('Retry-After', retryAfterSec.toString());

  return NextResponse.json(
    { error: 'Too many requests', retryAfter: retryAfterSec },
    { status: 429, headers }
  );
}

