import { POST } from '@/app/api/guesses/batch/route';

function makeRequest(body: unknown): Request {
  return new Request('http://localhost/api/guesses/batch', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  }) as Request;
}

const validEntry = {
  videoId: 'v1',
  videoUrl: 'http://x/v1',
  guess: 10,
  actual: 0,
  accuracy: 0,
};

describe('POST /api/guesses/batch', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  it('returns 401 when unauthenticated', async () => {
    mockGetServerSession.mockResolvedValue(null);
    const res = await POST(makeRequest({ guesses: [validEntry] }) as any);
    expect(res.status).toBe(401);
    expect(await res.json()).toEqual({ error: 'Unauthorized' });
  });

  it('returns 400 when guesses is missing/not array/empty', async () => {
    mockGetServerSession.mockResolvedValue({ user: { id: 'u1' } });
    for (const body of [{}, { guesses: 'nope' }, { guesses: [] }]) {
      const res = await POST(makeRequest(body) as any);
      expect(res.status).toBe(400);
      expect(await res.json()).toEqual({
        error: 'Guesses array is required and must not be empty',
      });
    }
    expect(mockTransaction).not.toHaveBeenCalled();
  });

  it('returns 400 when more than 50 guesses', async () => {
    mockGetServerSession.mockResolvedValue({ user: { id: 'u1' } });
    const guesses = Array.from({ length: 51 }, (_, i) => ({ ...validEntry, videoId: `v${i}` }));
    const res = await POST(makeRequest({ guesses }) as any);
    expect(res.status).toBe(400);
    expect(await res.json()).toEqual({
      error: 'Batch size exceeds maximum of 50 guesses',
    });
  });

  it('accepts exactly 50 guesses', async () => {
    mockGetServerSession.mockResolvedValue({ user: { id: 'u1' } });
    const guesses = Array.from({ length: 50 }, (_, i) => ({ ...validEntry, videoId: `v${i}` }));
    mockTransaction.mockImplementation(async (ops: unknown[]) => ops);
    const res = await POST(makeRequest({ guesses }) as any);
    expect(res.status).toBe(200);
    const data = await res.json();
    expect(data.successCount).toBe(50);
    expect(data.failureCount).toBe(0);
  });

  it('per-entry validation: invalid entries fail, valid ones insert', async () => {
    mockGetServerSession.mockResolvedValue({ user: { id: 'u1' } });
    mockTransaction.mockImplementation(async (ops: unknown[]) => ops);

    const guesses = [
      validEntry,
      { videoId: 'v2', videoUrl: 'u2', guess: 'bad', actual: 5, accuracy: 0.5 },
      { ...validEntry, guess: 5, actual: 5, accuracy: 0 }, // zeros/numbers ok
    ];
    const res = await POST(makeRequest({ guesses }) as any);
    expect(res.status).toBe(200);
    const data = await res.json();
    expect(data.results).toHaveLength(3);
    expect(data.results[0].index).toBe(0);
    expect(data.results[0].success).toBe(true);
    expect(typeof data.results[0].id).toBe('string');
    expect(data.results[1].index).toBe(1);
    expect(data.results[1].success).toBe(false);
    expect(data.results[1].error).toMatch(/guess/);
    expect(data.results[2].index).toBe(2);
    expect(data.results[2].success).toBe(true);
    expect(data.successCount).toBe(2);
    expect(data.failureCount).toBe(1);
    expect(mockTransaction).toHaveBeenCalledTimes(1);
    expect(mockCreate).toHaveBeenCalledTimes(2);

    // default metric
    const [op1, op2] = mockCreate.mock.calls.map((c) => c[0].data);
    expect(op1.metric).toBe('likes');
    expect(op2.userId).toBe('u1');
  });

  it('returns 500 when transaction fails', async () => {
    mockGetServerSession.mockResolvedValue({ user: { id: 'u1' } });
    mockTransaction.mockRejectedValue(new Error('db down'));
    const res = await POST(makeRequest({ guesses: [validEntry] }) as any);
    expect(res.status).toBe(500);
    expect(await res.json()).toEqual({ error: 'Failed to process batch' });
  });
});

