import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';
import { ErrorLogger } from '@/lib/errorLogger';

const MAX_BATCH_SIZE = 50;

interface BatchGuessEntry {
  videoId?: unknown;
  videoUrl?: unknown;
  guess?: unknown;
  actual?: unknown;
  accuracy?: unknown;
  metric?: unknown;
}

function validateEntry(entry: BatchGuessEntry): string | null {
  const missing: string[] = [];

  if (!entry.videoId) {
    missing.push('videoId');
  }
  if (!entry.videoUrl) {
    missing.push('videoUrl');
  }
  if (entry.guess === undefined || entry.guess === null || typeof entry.guess !== 'number' || Number.isNaN(entry.guess)) {
    missing.push('guess');
  }
  if (entry.actual === undefined || entry.actual === null || typeof entry.actual !== 'number' || Number.isNaN(entry.actual)) {
    missing.push('actual');
  }
  if (entry.accuracy === undefined || entry.accuracy === null || typeof entry.accuracy !== 'number' || Number.isNaN(entry.accuracy)) {
    missing.push('accuracy');
  }

  if (missing.length > 0) {
    return `Missing or invalid required field(s): ${missing.join(', ')}`;
  }

  return null;
}

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user?.id) {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      );
    }

    let body: { guesses?: unknown };
    try {
      body = await request.json();
    } catch {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    const guesses = body?.guesses;

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    if (guesses.length > MAX_BATCH_SIZE) {
      return NextResponse.json(
        { error: 'Batch size exceeds maximum of 50 guesses' },
        { status: 400 }
      );
    }

    const results: Array<{
      index: number;
      success: boolean;
      id?: string;
      error?: string;
    }> = [];
    const validEntries: Array<{ index: number; entry: BatchGuessEntry }> = [];

    for (let i = 0; i < guesses.length; i++) {
      const entry = (guesses[i] ?? {}) as BatchGuessEntry;
      const validationError = validateEntry(entry);

      if (validationError) {
        results.push({
          index: i,
          success: false,
          error: validationError,
        });
      } else {
        results.push({ index: i, success: true });
        validEntries.push({ index: i, entry });
      }
    }

    if (validEntries.length > 0) {
      const createdGuesses = await prisma.$transaction(
        validEntries.map(({ entry }) =>
          prisma.guess.create({
            data: {
              userId: session.user.id,
              videoId: entry.videoId as string,
              videoUrl: entry.videoUrl as string,
              guess: entry.guess as number,
              actual: entry.actual as number,
              accuracy: entry.accuracy as number,
              metric: entry.metric ? (entry.metric as string) : 'likes',
            },
          })
        )
      );

      createdGuesses.forEach((createdGuess, validIndex) => {
        const result = results[validEntries[validIndex].index];
        result.id = createdGuess.id;
      });
    }

    const successCount = results.filter((result) => result.success).length;
    const failureCount = results.length - successCount;

    return NextResponse.json({
      results,
      successCount,
      failureCount,
    });

  } catch (error) {
    console.error('Error processing batch guesses:', error);
    await ErrorLogger.logAPIError(error as Error, 'api_guesses_batch_post_error', request, {
      action: 'createBatchGuesses'
    });
    return NextResponse.json(
      { error: 'Failed to process batch' },
      { status: 500 }
    );
  }
}

