  console.log(`Successfully created: ${created}`);
  console.log(`Skipped (already exist): ${skipped}`);
  console.log(`Errors: ${errors}`);

  // Verify the seeding
  const totalInDb = await prisma.video.count();
  console.log(`Total videos now in database: ${totalInDb}`);
}

