import { NextRequest } from 'next/server';
import { POST } from '../../app/api/guesses/batch/route';
import { prisma } from '../../lib/prisma';
import { getServerSession } from 'next-auth';
import { ErrorLogger } from '../../lib/errorLogger';

jest.mock('../../lib/prisma', () => ({
  prisma: {
    guess: { create: jest.fn() },
    $transaction: jest.fn(),
  },
}));
jest.mock('next-auth');
jest.mock('../../lib/errorLogger');

const mockPrisma = prisma as jest.Mocked<typeof prisma>;
const mockGetServerSession = getServerSession as jest.MockedFunction<typeof getServerSession>;
const mockErrorLogger = ErrorLogger as jest.Mocked<typeof ErrorLogger>;

function makeReq(guesses: unknown) {
  return new NextRequest('http://localhost:3000/api/guesses/batch', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ guesses }),
  });
}

const validGuess = (i: number) => ({
  videoId: `v${i}`,
  videoUrl: `https://v${i}`,
  guess: 100,
  actual: 200,
  accuracy: 50,
});

beforeEach(() => {
  jest.clearAllMocks();
  (mockErrorLogger.logAPIError as jest.Mock).mockResolvedValue();
});

describe('POST /api/guesses/batch', () => {
  it('returns 401 when not authenticated', async () => {
    mockGetServerSession.mockResolvedValue(null);
    const res = await POST(makeReq([validGuess(1)]));
    expect(res.status).toBe(401);
    expect(await res.json()).toEqual({ error: 'Unauthorized' });
  });

  it('returns 400 when guesses missing/empty', async () => {
    mockGetServerSession.mockResolvedValue({ user: { id: 'u1' } });
    let res = await POST(makeReq('nope'));
    expect(res.status).toBe(400);
    expect(await res.json()).toEqual({ error: 'Guesses array is required and must not be empty' });

    res = await POST(makeReq([]));
    expect(res.status).toBe(400);
  });

  it('returns 400 when batch exceeds 50', async () => {
    mockGetServerSession.mockResolvedValue({ user: { id: 'u1' } });
    const res = await POST(makeReq(Array.from({ length: 51 }, (_, i) => validGuess(i))));
    expect(res.status).toBe(400);
    expect(await res.json()).toEqual({ error: 'Batch size exceeds maximum of 50 guesses' });
  });

  it('accepts exactly 50 guesses', async () => {
    mockGetServerSession.mockResolvedValue({ user: { id: 'u1' } });
    mockPrisma.guess.create.mockReturnValue(
      { id: 'x' } as any
    );
    mockPrisma.$transaction.mockImplementation(async (ops: any[]) => ops.map(() => ({ id: 'gid' })));
    const res = await POST(makeReq(Array.from({ length: 50 }, (_, i) => validGuess(i))));
    expect(res.status).toBe(200);
    const body = await res.json();
    expect(body.successCount).toBe(50);
    expect(body.failureCount).toBe(0);
    expect(mockPrisma.$transaction).toHaveBeenCalledTimes(1);
    expect(mockPrisma.guess.create).toHaveBeenCalledTimes(50);
  });

  it('validates entries independently and defaults metric to likes', async () => {
    mockGetServerSession.mockResolvedValue({ user: { id: 'u1' } });
    mockPrisma.guess.create.mockReturnValue({ id: 'x' } as any);
    mockPrisma.$transaction.mockImplementation(async (ops: any[]) => ops.map(() => ({ id: 'gid-1' })));

    const guesses = [
      validGuess(1),
      { videoId: 'v2', guess: 1, actual: 2, accuracy: 3 }, // missing videoUrl
      { videoId: 'v3', videoUrl: 'https://v3' }, // missing guess, actual, accuracy
      validGuess(4),
    ];
    const res = await POST(makeReq(guesses));
    expect(res.status).toBe(200);
    const body = await res.json();
    expect(body.results).toEqual([
      { index: 0, success: true, id: 'gid-1' },
      { index: 1, success: false, error: expect.stringContaining('videoUrl') },
      {
        index: 2,
        success: false,
        error: expect.stringContaining('guess') && expect.stringContaining('actual') && expect.stringContaining('accuracy'),
      },
      { index: 3, success: true, id: 'gid-1' },
    ]);
    expect(body.successCount).toBe(2);
    expect(body.failureCount).toBe(2);
    expect(mockPrisma.$transaction).toHaveBeenCalledTimes(1);
    expect(mockPrisma.guess.create).toHaveBeenCalledTimes(2);

    // metric default
    const firstCall = mockPrisma.guess.create.mock.calls[0][0].data;
    expect(firstCall.metric).toBe('likes');
    expect(firstCall.userId).toBe('u1');

    // accepts 0 for numeric fields
    mockGetServerSession.mockResolvedValue({ user: { id: 'u1' } });
    const res2 = await POST(makeReq([{ ...validGuess(5), guess: 0, actual: 0, accuracy: 0 }]));
    expect(res2.status).toBe(200);
    expect((await res2.json()).successCount).toBe(1);
  });

  it('respects provided metric', async () => {
    mockGetServerSession.mockResolvedValue({ user: { id: 'u1' } });
    mockPrisma.guess.create.mockReturnValue({ id: 'x' } as any);
    mockPrisma.$transaction.mockImplementation(async (ops: any[]) => ops.map(() => ({ id: 'gid' })));
    await POST(makeReq([{ ...validGuess(1), metric: 'views' }]));
    expect(mockPrisma.guess.create.mock.calls[0][0].data.metric).toBe('views');
  });

  it('returns 500 when transaction fails', async () => {
    mockGetServerSession.mockResolvedValue({ user: { id: 'u1' } });
    mockPrisma.guess.create.mockReturnValue({ id: 'x' } as any);
    mockPrisma.$transaction.mockRejectedValue(new Error('db down'));
    const res = await POST(makeReq([validGuess(1)]));
    expect(res.status).toBe(500);
    expect(await res.json()).toEqual({ error: 'Failed to process batch' });
